import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-matplotlib-image-thumbnail":{"intro":"This lab will guide you through the process of generating thumbnails from existing images using Matplotlib library in Python. Thumbnails are smaller versions of images that can be used to display a preview of the larger image. Matplotlib depends on Pillow library for reading images and supports all formats supported by Pillow.","steps":[{"title":"Install Required Libraries","body":[],"code":[{"lang":"python","text":"pip install matplotlib\npip install pillow"}]},{"title":"Import Libraries","body":["In this step, you will import the libraries you installed in the previous step. You need to import ArgumentParser and Path from argparse and pathlib modules respectively. Also, import sys and image modules from sys and matplotlib.image modules respectively."],"code":[{"lang":"python","text":"from argparse import ArgumentParser\nfrom pathlib import Path\nimport sys\nimport matplotlib.image as image"}]},{"title":"Parse Arguments","body":["In this step, you will parse the arguments passed to your program. You need to create an ArgumentParser object and add an argument named imagedir. This argument specifies the path to the directory containing the images. You can use the type parameter to specify the data type of the argument. In this case, the argument should be of type Path."],"code":[{"lang":"python","text":"parser = ArgumentParser(description=\"Build thumbnails of all images in a directory.\")\nparser.add_argument(\"imagedir\", type=Path)\nargs = parser.parse_args()"}]},{"title":"Verify Directory","body":["In this step, you will check if the specified directory exists. If the directory does not exist, you will exit the program and print an error message."],"code":[{"lang":"python","text":"if not args.imagedir.is_dir():\n    sys.exit(f\"Could not find input directory {args.imagedir}\")"}]},{"title":"Create Output Directory","body":["In this step, you will create a directory named thumbs where the thumbnails will be saved. If the directory already exists, it will not be created again."],"code":[{"lang":"python","text":"outdir = Path(\"thumbs\")\noutdir.mkdir(parents=True, exist_ok=True)"}]},{"title":"Generate Thumbnails","body":["In this step, you will generate thumbnails for all the images in the specified directory. You will use a for loop to iterate over all the images with the .png extension in the specified directory. For each image, you will generate a thumbnail and save it in the thumbs directory."],"code":[{"lang":"python","text":"for path in args.imagedir.glob(\"*.png\"):\n    outpath = outdir / path.name\n    fig = image.thumbnail(path, outpath, scale=0.15)\n    print(f\"saved thumbnail of {path} to {outpath}\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"for path in args.imagedir.glob(\"*.png\"):\n    outpath = outdir / path.name\n    fig = image.thumbnail(path, outpath, scale=0.15)\n    print(f\"saved thumbnail of {path} to {outpath}\")"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-image-transparency":{"intro":"This lab will show you how to blend transparency with color in 2D images using Matplotlib. The goal is to highlight certain parts of data with imshow.","steps":[{"title":"Generate Data","body":["We will start by generating two 2D blobs in a 2D grid. One blob will be positive, and the other negative."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.colors import Normalize\n\ndef normal_pdf(x, mean, var):\n    return np.exp(-(x - mean)**2 / (2*var))\n\n# Generate the space in which the blobs will live\nxmin, xmax, ymin, ymax = (0, 100, 0, 100)\nn_bins = 100\nxx = np.linspace(xmin, xmax, n_bins)\nyy = np.linspace(ymin, ymax, n_bins)\n\n# Generate the blobs. The range of the values is roughly -.0002 to .0002\nmeans_high = [20, 50]\nmeans_low = [50, 60]\nvar = [150, 200]\n\ngauss_x_high = normal_pdf(xx, means_high[0], var[0])\ngauss_y_high = normal_pdf(yy, means_high[1], var[0])\n\ngauss_x_low = normal_pdf(xx, means_low[0], var[1])\ngauss_y_low = normal_pdf(yy, means_low[1], var[1])\n\nweights = (np.outer(gauss_y_high, gauss_x_high)\n           - np.outer(gauss_y_low, gauss_x_low))\n\n# We'll also create a grey background into which the pixels will fade\ngreys = np.full((*weights.shape, 3), 70, dtype=np.uint8)"}]},{"title":"Plot the Blobs","body":["Next, we will plot these blobs using imshow without transparency."],"code":[{"lang":"python","text":"vmax = np.abs(weights).max()\nimshow_kwargs = {\n    'vmax': vmax,\n    'vmin': -vmax,\n    'cmap': 'RdYlBu',\n    'extent': (xmin, xmax, ymin, ymax),\n}\n\nfig, ax = plt.subplots()\nax.imshow(greys)\nax.imshow(weights, **imshow_kwargs)\nax.set_axis_off()\nplt.show()"}]},{"title":"Blend in Transparency","body":["The simplest way to include transparency when plotting data with imshow is to pass an array matching the shape of the data to the alpha argument."],"code":[{"lang":"python","text":"# Create an alpha channel of linearly increasing values moving to the right.\nalphas = np.ones(weights.shape)\nalphas[:, 30:] = np.linspace(1, 0, 70)\n\n# Create the figure and image\nfig, ax = plt.subplots()\nax.imshow(greys)\nax.imshow(weights, alpha=alphas, **imshow_kwargs)\nax.set_axis_off()\nplt.show()"}]},{"title":"Use Transparency to Highlight Values","body":["Use Transparency to Highlight Values","Finally, we'll recreate the same plot, but this time we'll use transparency to highlight the extreme values in the data. This is often used to highlight data points with smaller p-values. We'll also add in contour lines to highlight the image values."],"code":[{"lang":"python","text":"# Create an alpha channel based on weight values\nalphas = Normalize(0, .3, clip=True)(np.abs(weights))\nalphas = np.clip(alphas, .4, 1)  # alpha value clipped at the bottom at .4\n\n# Create the figure and image\nfig, ax = plt.subplots()\nax.imshow(greys)\nax.imshow(weights, alpha=alphas, **imshow_kwargs)\n\n# Add contour lines to further highlight different levels.\nax.contour(weights[::-1], levels=[-.1, .1], colors='k', linestyles='-')\nax.set_axis_off()\nplt.show()\n\nax.contour(weights[::-1], levels=[-.0001, .0001], colors='k', linestyles='-')\nax.set_axis_off()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create an alpha channel based on weight values\nalphas = Normalize(0, .3, clip=True)(np.abs(weights))\nalphas = np.clip(alphas, .4, 1)  # alpha value clipped at the bottom at .4\n\n# Create the figure and image\nfig, ax = plt.subplots()\nax.imshow(greys)\nax.imshow(weights, alpha=alphas, **imshow_kwargs)\n\n# Add contour lines to further highlight different levels.\nax.contour(weights[::-1], levels=[-.1, .1], colors='k', linestyles='-')\nax.set_axis_off()\nplt.show()\n\nax.contour(weights[::-1], levels=[-.0001, .0001], colors='k', linestyles='-')\nax.set_axis_off()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-modifying-coordinate-formatter-in-matplotlib":{"intro":"Matplotlib is a library used for data visualization in Python. It provides a wide range of tools for creating various types of plots, graphs, and charts. One of the useful features of Matplotlib is the ability to customize the coordinate formatter. In this lab, we will go through the steps of modifying the coordinate formatter in Matplotlib to report the image 'z' value of the nearest pixel given x and y.","steps":[{"title":"Import necessary modules","body":["To begin, we need to import the necessary modules. In this case, we will import matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a random matrix","body":["Next, we will create a random matrix using numpy. We will use the rand method to create a 5x3 matrix with random values between 0 and 1. We will also set a random seed to ensure reproducibility of the results."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nX = 10*np.random.rand(5, 3)"}]},{"title":"Create a plot","body":["Now, we will create a plot of the matrix using imshow method of the Matplotlib axes class."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.imshow(X)"}]},{"title":"Modify coordinate formatter","body":["We will now modify the coordinate formatter to report the image \"z\" value of the nearest pixel given x and y. This can be achieved by customizing the ~.axes.Axes.format_coord function."],"code":[{"lang":"python","text":"def format_coord(x, y):\n    col = round(x)\n    row = round(y)\n    nrows, ncols = X.shape\n    if 0 <= col < ncols and 0 <= row < nrows:\n        z = X[row, col]\n        return f'x={x:1.4f}, y={y:1.4f}, z={z:1.4f}'\n    else:\n        return f'x={x:1.4f}, y={y:1.4f}'\n\nax.format_coord = format_coord"}]},{"title":"Display the plot","body":["Finally, we will display the plot using plt.show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-inset-locator":{"intro":"Matplotlib is a data visualization library in Python. The .inset_locator feature allows for easy placement of insets in the corners of the axes. In this lab, we will explore how to use the .inset_locator feature to create insets in Matplotlib plots.","steps":[{"title":"Create a Figure with Two Subplots","body":["Create a Figure with Two Subplots","First, we need to create a figure with two subplots. We will use the plt.subplots() method to create a figure with two subplots side by side."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig, (ax, ax2) = plt.subplots(1, 2, figsize=[5.5, 2.8])"}]},{"title":"Create Inset Axes","body":["Next, we will create inset axes in each of the subplots. We will use the inset_axes() method to create the inset axes. We will create four insets with different sizes and locations."],"code":[{"lang":"python","text":"from mpl_toolkits.axes_grid1.inset_locator import inset_axes\n\n# Create inset of width 1.3 inches and height 0.9 inches\n# at the default upper right location\naxins = inset_axes(ax, width=1.3, height=0.9)\n\n# Create inset of width 30% and height 40% of the parent axes' bounding box\n# at the lower left corner (loc=3)\naxins2 = inset_axes(ax, width=\"30%\", height=\"40%\", loc=3)\n\n# Create inset of mixed specifications in the second subplot;\n# width is 30% of parent axes' bounding box and\n# height is 1 inch at the upper left corner (loc=2)\naxins3 = inset_axes(ax2, width=\"30%\", height=1., loc=2)\n\n# Create an inset in the lower right corner (loc=4) with borderpad=1, i.e.\n# 10 points padding (as 10pt is the default fontsize) to the parent axes\naxins4 = inset_axes(ax2, width=\"20%\", height=\"20%\", loc=4, borderpad=1)"}]},{"title":"Turn Off Tick Labels","body":["To remove the tick labels from each of the insets, we can use the tick_params() method and set labelleft and labelbottom to False."],"code":[{"lang":"python","text":"# Turn ticklabels of insets off\nfor axi in [axins, axins2, axins3, axins4]:\n    axi.tick_params(labelleft=False, labelbottom=False)"}]},{"title":"Control Inset Position and Size","body":["Control Inset Position and Size","We can use the bbox_to_anchor and bbox_transform parameters to control the position and size of the inset. These parameters allow for fine-grained control over the inset position and size or even to position the inset at completely arbitrary positions."],"code":[{"lang":"python","text":"# We use the axes transform as bbox_transform. Therefore, the bounding box\n# needs to be specified in axes coordinates ((0, 0) is the lower left corner\n# of the axes, (1, 1) is the upper right corner).\n# The bounding box (.2, .4, .6, .5) starts at (.2, .4) and ranges to (.8, .9)\n# in those coordinates.\n# Inside this bounding box an inset of half the bounding box' width and\n# three quarters of the bounding box' height is created. The lower left corner\n# of the inset is aligned to the lower left corner of the bounding box (loc=3).\n# The inset is then offset by the default 0.5 in units of the font size.\naxins = inset_axes(ax, width=\"50%\", height=\"75%\",\n                   bbox_to_anchor=(.2, .4, .6, .5),\n                   bbox_transform=ax.transAxes, loc=3)"}]},{"title":"Create Insets with Arbitrary Positions","body":["Create Insets with Arbitrary Positions","We can create insets with arbitrary positions by using the bbox_to_anchor parameter to specify a bounding box in data coordinates and using the bbox_transform parameter to specify the transform for the bounding box."],"code":[{"lang":"python","text":"# Create inset in data coordinates using ax.transData as transform\naxins3 = inset_axes(ax2, width=\"100%\", height=\"100%\",\n                    bbox_to_anchor=(1e-2, 2, 1e3, 3),\n                    bbox_transform=ax2.transData, loc=2, borderpad=0)"}]},{"title":"Create an Inset Outside the Axes","body":["Create an Inset Outside the Axes","We can create an inset outside the axes by using the bbox_to_anchor parameter to specify a bounding box in axes coordinates that extends outside the axes."],"code":[{"lang":"python","text":"# Create an inset outside the axes\naxins = inset_axes(ax, width=\"100%\", height=\"100%\",\n                   bbox_to_anchor=(1.05, .6, .5, .4),\n                   bbox_transform=ax.transAxes, loc=2, borderpad=0)"}]},{"title":"Create an Inset with a 2-Tuple Bounding Box","body":["Create an Inset with a 2-Tuple Bounding Box","We can create an inset with a 2-tuple bounding box by specifying the width and height in inches and using the bbox_to_anchor parameter to specify the lower left corner of the inset."],"code":[{"lang":"python","text":"# Create an inset with a 2-tuple bounding box. Note that this creates a\n# bbox without extent. This hence only makes sense when specifying\n# width and height in absolute units (inches).\naxins2 = inset_axes(ax, width=0.5, height=0.4,\n                    bbox_to_anchor=(0.33, 0.25),\n                    bbox_transform=ax.transAxes, loc=3, borderpad=0)"}]},{"title":"Create an Inset Centered in Figure Coordinates","body":["Create an Inset Centered in Figure Coordinates","We can create an inset that is horizontally centered in figure coordinates and vertically bound to line up with the axes by using the blended_transform_factory() method to create a blended transform and using it as the bbox_transform parameter."],"code":[{"lang":"python","text":"# Create an inset horizontally centered in figure coordinates and vertically\n# bound to line up with the axes.\nfrom matplotlib.transforms import blended_transform_factory\n\ntransform = blended_transform_factory(fig.transFigure, ax2.transAxes)\naxins4 = inset_axes(ax2, width=\"16%\", height=\"34%\",\n                    bbox_to_anchor=(0, 0, 1, 1),\n                    bbox_transform=transform, loc=8, borderpad=0)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create an inset horizontally centered in figure coordinates and vertically\n# bound to line up with the axes.\nfrom matplotlib.transforms import blended_transform_factory\n\ntransform = blended_transform_factory(fig.transFigure, ax2.transAxes)\naxins4 = inset_axes(ax2, width=\"16%\", height=\"34%\",\n                    bbox_to_anchor=(0, 0, 1, 1),\n                    bbox_transform=transform, loc=8, borderpad=0)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-zoomed-inset-with-matplotlib":{"intro":"Matplotlib is a popular data visualization library in Python. It provides many tools to create different types of plots and graphs. One of the useful features of Matplotlib is the ability to zoom in on a particular region of a plot, which can help to analyze data more closely. In this lab, we will learn how to create a zoomed inset using Matplotlib.","steps":[{"title":"Import necessary libraries","body":["Before we start creating the zoomed inset, we need to import the necessary libraries. We will be using matplotlib.pyplot and numpy for this lab."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a figure and subplots","body":["Next, we will create a figure and subplots to display our data. We will create two subplots side-by-side to show two different examples of zoomed insets."],"code":[{"lang":"python","text":"fig, (ax, ax2) = plt.subplots(ncols=2, figsize=[6, 3])"}]},{"title":"Create a zoomed inset with a size bar","body":["Create a zoomed inset with a size bar","In the first subplot, we will create a zoomed inset with a size bar. This will show how to use the .zoomed_inset_axes method to create a zoomed inset."],"code":[{"lang":"python","text":"# Set the aspect ratio of the plot to 1\nax.set_aspect(1)\n\n# Create a zoomed inset in the upper right corner of the plot\naxins = zoomed_inset_axes(ax, zoom=0.5, loc='upper right')\n\n# Set the number of ticks on the inset axes\naxins.yaxis.get_major_locator().set_params(nbins=7)\naxins.xaxis.get_major_locator().set_params(nbins=7)\n\n# Hide the tick labels on the inset axes\naxins.tick_params(labelleft=False, labelbottom=False)\n\n# Define a function to add a size bar to the plot\ndef add_sizebar(ax, size):\n    asb = AnchoredSizeBar(ax.transData,\n                          size,\n                          str(size),\n                          loc=8,\n                          pad=0.1, borderpad=0.5, sep=5,\n                          frameon=False)\n    ax.add_artist(asb)\n\n# Add a size bar to the main plot and the inset plot\nadd_sizebar(ax, 0.5)\nadd_sizebar(axins, 0.5)"}]},{"title":"Create an image with an inset zoom and a marked inset","body":["Create an image with an inset zoom and a marked inset","In the second subplot, we will create an image with an inset zoom and a marked inset. This will show how to use the .mark_inset method to mark the region of interest and connect it to the inset axes."],"code":[{"lang":"python","text":"# Load sample data for the image\nZ = cbook.get_sample_data(\"axes_grid/bivariate_normal.npy\")  # 15x15 array\nextent = (-3, 4, -4, 3)\nZ2 = np.zeros((150, 150))\nny, nx = Z.shape\nZ2[30:30+ny, 30:30+nx] = Z\n\n# Display the image in the subplot\nax2.imshow(Z2, extent=extent, origin=\"lower\")\n\n# Create a zoomed inset in the upper left corner of the plot\naxins2 = zoomed_inset_axes(ax2, zoom=6, loc=1)\n\n# Display the image in the inset plot\naxins2.imshow(Z2, extent=extent, origin=\"lower\")\n\n# Set the x and y limits of the inset plot to show the region of interest\nx1, x2, y1, y2 = -1.5, -0.9, -2.5, -1.9\naxins2.set_xlim(x1, x2)\naxins2.set_ylim(y1, y2)\n\n# Set the number of ticks on the inset axes\naxins2.yaxis.get_major_locator().set_params(nbins=7)\naxins2.xaxis.get_major_locator().set_params(nbins=7)\n\n# Hide the tick labels on the inset axes\naxins2.tick_params(labelleft=False, labelbottom=False)\n\n# Mark the region of interest and connect it to the inset axes\nmark_inset(ax2, axins2, loc1=2, loc2=4, fc=\"none\", ec=\"0.5\")"}]},{"title":"Display the plot","body":["Finally, we will display the plot using the plt.show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-simple-line-plot-with-matplotlib":{"intro":"This tutorial demonstrates how to use Python's Matplotlib library to create a simple line plot with a shaded region representing the area under the curve. The plot includes a text label, axis labels, and custom tick placement and labels.","steps":[{"title":"Define the function","body":["First, define the function that will be plotted. In this example, the function is (x - 3) _ (x - 5) _ (x - 7) + 85."],"code":[{"lang":"python","text":"def func(x):\n    return (x - 3) * (x - 5) * (x - 7) + 85"}]},{"title":"Define the integral limits","body":["Next, define the limits of the integral. In this example, the limits are a = 2 and b = 9."],"code":[{"lang":"python","text":"a, b = 2, 9"}]},{"title":"Create the x and y values","body":["Generate a range of x values using the numpy linspace function. Then, use the function defined in step 1 to generate the corresponding y values."],"code":[{"lang":"python","text":"import numpy as np\n\nx = np.linspace(0, 10)\ny = func(x)"}]},{"title":"Create the plot","body":["Create a figure and axis object using subplots. Plot the x and y values using plot. Set the y-axis limits to start at 0 using set_ylim."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot(x, y, 'r', linewidth=2)\nax.set_ylim(bottom=0)"}]},{"title":"Create the shaded region","body":["Create the shaded region using a Polygon patch. Generate x and y values for the region using linspace and the function defined in step 1. Then, define the vertices of the region as a list of tuples. Finally, create the Polygon object and add it to the axis using add_patch."],"code":[{"lang":"python","text":"from matplotlib.patches import Polygon\n\nix = np.linspace(a, b)\niy = func(ix)\nverts = [(a, 0), *zip(ix, iy), (b, 0)]\npoly = Polygon(verts, facecolor='0.9', edgecolor='0.5')\nax.add_patch(poly)"}]},{"title":"Add the integral label","body":["Add the integral label to the plot using text. The label should be centered at the midpoint between a and b and should be formatted using mathtext."],"code":[{"lang":"python","text":"ax.text(0.5 * (a + b), 30, r\"$\\int_a^b f(x)\\mathrm{d}x$\",\n        horizontalalignment='center', fontsize=20)"}]},{"title":"Add axis labels and tick labels","body":["Add axis labels and tick labels","Add the x and y-axis labels using figtext. Hide the top and right spines using spines. Set custom tick placement and labels using set_xticks and set_yticks."],"code":[{"lang":"python","text":"fig.text(0.9, 0.05, '$x$')\nfig.text(0.1, 0.9, '$y$')\n\nax.spines[['top', 'right']].set_visible(False)\nax.set_xticks([a, b], labels=['$a$', '$b$'])\nax.set_yticks([])"}]},{"title":"Show the plot","body":[],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-display-images-with-matplotlib":{"intro":"This tutorial will guide you through the process of displaying images using Matplotlib's imshow function. You will learn how to use different interpolation methods to display images with Matplotlib.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the required libraries. In this tutorial, we will be using Matplotlib and NumPy libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Random Grid","body":["The next step is to create a random grid of 4x4 using NumPy library."],"code":[{"lang":"python","text":"np.random.seed(19680801)\ngrid = np.random.rand(4, 4)"}]},{"title":"Define Interpolation Methods","body":["Define the list of interpolation methods which we want to use to display images."],"code":[{"lang":"python","text":"methods = [None, 'none', 'nearest', 'bilinear', 'bicubic', 'spline16',\n           'spline36', 'hanning', 'hamming', 'hermite', 'kaiser', 'quadric',\n           'catrom', 'gaussian', 'bessel', 'mitchell', 'sinc', 'lanczos']"}]},{"title":"Create Subplots","body":["Create subplots to display the images using interpolation methods."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=3, ncols=6, figsize=(9, 6),\n                        subplot_kw={'xticks': [], 'yticks': []})"}]},{"title":"Display Images","body":["Display the images using the imshow function and different interpolation methods."],"code":[{"lang":"python","text":"for ax, interp_method in zip(axs.flat, methods):\n    ax.imshow(grid, interpolation=interp_method, cmap='viridis')\n    ax.set_title(str(interp_method))"}]},{"title":"Show the Plot","body":["Show the plot using the show function of Matplotlib."],"code":[{"lang":"python","text":"plt.tight_layout()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.tight_layout()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-inverting-axes-of-a-matplotlib-plot":{"intro":"Inverting axes in a Matplotlib plot can be useful when visualizing data with a non-linear relationship. This lab will guide you through the process of inverting the axes of a plot using Matplotlib in Python.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the required libraries. In this lab, we will be using Matplotlib and NumPy. Matplotlib is a popular plotting library in Python, and NumPy is a library for scientific computing in Python."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["Next, we need to create some data to plot. In this example, we will create an array of values for time (t) and an array of values for voltage (s)."],"code":[{"lang":"python","text":"t = np.arange(0.01, 5.0, 0.01)\ns = np.exp(-t)"}]},{"title":"Create the Plot","body":["Now, we can create the plot using Matplotlib. We will use the plot function to plot our data and set the limits of the x-axis using the set_xlim function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nax.plot(t, s)\nax.set_xlim(5, 0)  # decreasing time\nax.set_xlabel('decreasing time (s)')\nax.set_ylabel('voltage (mV)')\nax.set_title('Should be growing...')\nax.grid(True)\n\nplt.show()"}]},{"title":"Invert the Axes","body":["To invert the x-axis, we simply need to reverse the order of the limits using the set_xlim function. In this example, we set the x-axis limits from 5 to 0, which effectively reverses the x-axis."],"code":[{"lang":"python","text":"ax.set_xlim(5, 0)  # decreasing time"}]},{"title":"View the Inverted Plot","body":["Finally, we can view the inverted plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-irregular-data-grid-contour-plotting":{"intro":"This lab demonstrates how to create a contour plot of irregularly spaced data in Python using Matplotlib. The contour plot shows the 2D distribution of data values using iso-contours or contour lines. In this example, we will compare a contour plot of irregularly spaced data interpolated on a regular grid versus a tricontour plot for an unstructured triangular grid.","steps":[{"title":"Import necessary libraries","body":["We start by importing the necessary libraries for this example: matplotlib.pyplot and numpy. Additionally, we import matplotlib.tri for triangulation of the data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.tri as tri"}]},{"title":"Generate random data","body":["We generate random data using NumPy's np.random.uniform method. We generate npts = 200 data points with x and y values between -2 and 2. We also calculate the z values using the function z = x * np.exp(-x**2 - y**2)."],"code":[{"lang":"python","text":"np.random.seed(19680801)\nnpts = 200\nx = np.random.uniform(-2, 2, npts)\ny = np.random.uniform(-2, 2, npts)\nz = x * np.exp(-x**2 - y**2)"}]},{"title":"Interpolation on a grid","body":["We create a contour plot of irregularly spaced data coordinates via interpolation on a grid. We first create grid values for x and y using np.linspace. We then linearly interpolate the data (x, y) on a grid defined by (xi, yi) using tri.LinearTriInterpolator. We plot the interpolated data with the usual axes.Axes.contour."],"code":[{"lang":"python","text":"ngridx = 100\nngridy = 200\nxi = np.linspace(-2.1, 2.1, ngridx)\nyi = np.linspace(-2.1, 2.1, ngridy)\n\ntriang = tri.Triangulation(x, y)\ninterpolator = tri.LinearTriInterpolator(triang, z)\nXi, Yi = np.meshgrid(xi, yi)\nzi = interpolator(Xi, Yi)\n\nfig, ax1 = plt.subplots()\ncntr1 = ax1.contourf(xi, yi, zi, levels=14, cmap=\"RdBu_r\")\nax1.plot(x, y, 'ko', ms=3)\nax1.set(xlim=(-2, 2), ylim=(-2, 2))\nax1.set_title('Contour Plot of Irregularly Spaced Data Interpolated on a Grid')\nfig.colorbar(cntr1, ax=ax1)\nplt.show()"}]},{"title":"Tricontour","body":["We plot the same data using a tricontour plot by directly supplying the unordered, irregularly spaced coordinates to axes.Axes.tricontour."],"code":[{"lang":"python","text":"fig, ax2 = plt.subplots()\ncntr2 = ax2.tricontourf(x, y, z, levels=14, cmap=\"RdBu_r\")\nax2.plot(x, y, 'ko', ms=3)\nax2.set(xlim=(-2, 2), ylim=(-2, 2))\nax2.set_title('Tricontour Plot of Irregularly Spaced Data')\nfig.colorbar(cntr2, ax=ax2)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax2 = plt.subplots()\ncntr2 = ax2.tricontourf(x, y, z, levels=14, cmap=\"RdBu_r\")\nax2.plot(x, y, 'ko', ms=3)\nax2.set(xlim=(-2, 2), ylim=(-2, 2))\nax2.set_title('Tricontour Plot of Irregularly Spaced Data')\nfig.colorbar(cntr2, ax=ax2)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-ishikawa-diagram-creation":{"intro":"In this lab, we will learn how to create an Ishikawa diagram, also known as a fishbone diagram or cause-and-effect diagram. Ishikawa diagrams are commonly used to identify problems in a system by showing how causes and effects are linked. We will use Python and the Matplotlib library to create the diagram.","steps":[{"title":"Install Matplotlib","body":["Before we begin, we need to make sure we have Matplotlib installed. If you haven't already, you can install it using the following command:"],"code":[{"lang":"python","text":"!pip install matplotlib"}]},{"title":"Import Libraries","body":["We will begin by importing the necessary libraries. We will be using Matplotlib and the Polygon and Wedge classes from the matplotlib.patches module."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.patches import Polygon, Wedge"}]},{"title":"Create the Fishbone Diagram","body":["Now we will create the fishbone diagram. We will start by creating a figure and axis object.","Next, we will set the x and y limits for the axis and turn off the axis."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(10, 6), layout='constrained')"},{"lang":"python","text":"ax.set_xlim(-5, 5)\nax.set_ylim(-5, 5)\nax.axis('off')"}]},{"title":"Define the Functions","body":["We will define three functions that we will use to create the diagram.","The first function is the problems function. This function takes in the category name, the x and y positions of the problem arrow, and the angle of the problem annotation. It uses the annotate method to create the problem arrow and annotation.","The second function is the causes function. This function takes in the list of causes, the x and y positions of the cause annotation, and whether the cause should be placed above or below the problem arrow. It uses the annotate method to create the cause annotation and arrow.","The third function is the draw body function. This function takes in the input data and uses it to create the fishbone diagram."],"code":[{"lang":"python","text":"def problems(data: str,\n             problem_x: float, problem_y: float,\n             prob_angle_x: float, prob_angle_y: float):\n    ax.annotate(str.upper(data), xy=(problem_x, problem_y),\n                xytext=(prob_angle_x, prob_angle_y),\n                fontsize='10',\n                color='white',\n                weight='bold',\n                xycoords='data',\n                verticalalignment='center',\n                horizontalalignment='center',\n                textcoords='offset fontsize',\n                arrowprops=dict(arrowstyle=\"->\", facecolor='black'),\n                bbox=dict(boxstyle='square',\n                          facecolor='tab:blue',\n                          pad=0.8))"},{"lang":"python","text":"def causes(data: list, cause_x: float, cause_y: float,\n           cause_xytext=(-9, -0.3), top: bool = True):\n    for index, cause in enumerate(data):\n        coords = [[0, [0, 0]],\n                  [0.23, [0.5, -0.5]],\n                  [-0.46, [-1, 1]],\n                  [0.69, [1.5, -1.5]],\n                  [-0.92, [-2, 2]],\n                  [1.15, [2.5, -2.5]]]\n        if top:\n            cause_y += coords[index][1][0]\n        else:\n            cause_y += coords[index][1][1]\n        cause_x -= coords[index][0]\n        ax.annotate(cause, xy=(cause_x, cause_y),\n                    horizontalalignment='center',\n                    xytext=cause_xytext,\n                    fontsize='9',\n                    xycoords='data',\n                    textcoords='offset fontsize',\n                    arrowprops=dict(arrowstyle=\"->\",\n                                    facecolor='black'))"},{"lang":"python","text":"def draw_body(data: dict):\n    second_sections = []\n    third_sections = []\n    if len(data) == 1 or len(data) == 2:\n        spine_length = (-2.1, 2)\n        head_pos = (2, 0)\n        tail_pos = ((-2.8, 0.8), (-2.8, -0.8), (-2.0, -0.01))\n        first_section = [1.6, 0.8]\n    elif len(data) == 3 or len(data) == 4:\n        spine_length = (-3.1, 3)\n        head_pos = (3, 0)\n        tail_pos = ((-3.8, 0.8), (-3.8, -0.8), (-3.0, -0.01))\n        first_section = [2.6, 1.8]\n        second_sections = [-0.4, -1.2]\n    else:  # len(data) == 5 or 6\n        spine_length = (-4.1, 4)\n        head_pos = (4, 0)\n        tail_pos = ((-4.8, 0.8), (-4.8, -0.8), (-4.0, -0.01))\n        first_section = [3.5, 2.7]\n        second_sections = [1, 0.2]\n        third_sections = [-1.5, -2.3]\n\n    for index, problem in enumerate(data.values()):\n        top_row = True\n        cause_arrow_y = 1.7\n        if index % 2 != 0:\n            top_row = False\n            y_prob_angle = -16\n            cause_arrow_y = -1.7\n        else:\n            y_prob_angle = 16\n        if index in (0, 1):\n            prob_arrow_x = first_section[0]\n            cause_arrow_x = first_section[1]\n        elif index in (2, 3):\n            prob_arrow_x = second_sections[0]\n            cause_arrow_x = second_sections[1]\n        else:\n            prob_arrow_x = third_sections[0]\n            cause_arrow_x = third_sections[1]\n        if index > 5:\n            raise ValueError(f'Maximum number of problems is 6, you have entered '\n                             f'{len(data)}')\n        ax.plot(spine_length, [0, 0], color='tab:blue', linewidth=2)\n        ax.text(head_pos[0] + 0.1, head_pos[1] - 0.05, 'PROBLEM', fontsize=10,\n                weight='bold', color='white')\n        semicircle = Wedge(head_pos, 1, 270, 90, fc='tab:blue')\n        ax.add_patch(semicircle)"}]},{"title":"Input Data","body":["Now we will define the input data. The data should be a dictionary where the keys are the categories and the values are lists of causes."],"code":[{"lang":"python","text":"categories = {\n    'Method': ['Time consumption', 'Cost', 'Procedures', 'Inefficient process', 'Sampling'],\n    'Machine': ['Faulty equipment', 'Compatibility'],\n    'Material': ['Poor-quality input', 'Raw materials', 'Supplier', 'Shortage'],\n    'Measurement': ['Calibration', 'Performance', 'Wrong measurements'],\n    'Environment': ['Bad conditions'],\n    'People': ['Lack of training', 'Managers', 'Labor shortage', 'Procedures', 'Sales strategy']\n}"}]},{"title":"Draw the Fishbone Diagram","body":["Finally, we will call the draw body function and show the diagram."],"code":[{"lang":"python","text":"draw_body(categories)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"draw_body(categories)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-joinstyle-for-beginners":{"intro":"This lab provides a step-by-step guide on how to use the JoinStyle module of Matplotlib in Python. JoinStyle controls how Matplotlib draws the corners where two different line segments meet. This lab is designed for users who are new to Matplotlib.","steps":[{"title":"Importing Required Libraries","body":["In order to use the JoinStyle module, we need to import it from the matplotlib._enums library. We also need to import the pyplot module from matplotlib to create a graph."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib._enums import JoinStyle"}]},{"title":"Creating a Graph","body":["To create a graph, we first need to define the data that we want to plot. In this example, we will use the numpy library to generate some sample data.","Next, we create a new figure and axis using plt.subplots(). We will set the x and y limits of the graph and then plot the data using plot()."],"code":[{"lang":"python","text":"import numpy as np\n\nx = np.linspace(0, 10, 1000)\ny = np.sin(x)"},{"lang":"python","text":"fig, ax = plt.subplots()\nax.set_xlim([0, 10])\nax.set_ylim([-1.2, 1.2])\nax.plot(x, y)"}]},{"title":"Setting JoinStyle","body":["We can set the JoinStyle of the line using the set_solid_joinstyle() method of the Line2D object. We will create a new line object and set its join style to JoinStyle.bevel."],"code":[{"lang":"python","text":"line = ax.lines[0]\nline.set_solid_joinstyle(JoinStyle.bevel)"}]},{"title":"Displaying the Graph","body":["Finally, we display the graph using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-connecting-to-keypress-events":{"intro":"In this lab, we will learn how to connect to keypress events in Matplotlib, which allows us to perform certain actions when a key is pressed. We will create a plot and set up a keypress event listener that will toggle the visibility of the x-label when the 'x' key is pressed.","steps":[{"title":"Import Libraries","body":["We begin by importing the required libraries: matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the Keypress Event Function","body":["Define the Keypress Event Function","Next, we define a function on_press that will be called when a key is pressed. This function takes an event parameter which contains information about the key that was pressed. In this example, we will toggle the visibility of the x-label when the 'x' key is pressed."],"code":[{"lang":"python","text":"def on_press(event):\n    print('press', event.key)\n    sys.stdout.flush()\n    if event.key == 'x':\n        visible = xl.get_visible()\n        xl.set_visible(not visible)\n        fig.canvas.draw()"}]},{"title":"Create the Plot and Connect the Keypress Event Listener","body":["Create the Plot and Connect the Keypress Event Listener","We create a simple plot using np.random.rand() to generate random data. Then, we set up the keypress event listener using fig.canvas.mpl_connect() and passing in the name of the event we want to listen for ('key_press_event') and the function we want to call when the event occurs (on_press)."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nfig.canvas.mpl_connect('key_press_event', on_press)\n\nax.plot(np.random.rand(12), np.random.rand(12), 'go')\nxl = ax.set_xlabel('easy come, easy go')\nax.set_title('Press a key')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\n\nfig.canvas.mpl_connect('key_press_event', on_press)\n\nax.plot(np.random.rand(12), np.random.rand(12), 'go')\nxl = ax.set_xlabel('easy come, easy go')\nax.set_title('Press a key')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-plotting-with-keywords":{"intro":"In this lab, you will learn how to generate plots using strings corresponding to variables using the numpy.recarray or pandas.DataFrame data format with the data keyword argument in Matplotlib.","steps":[{"title":"Import Required Libraries","body":["In this step, we will import the necessary libraries to generate plots using keywords."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Set Seed Value","body":["In this step, we will set the seed value for the random number generator to ensure that the results are reproducible."],"code":[{"lang":"python","text":"np.random.seed(19680801)"}]},{"title":"Create Data","body":["In this step, we will create a dictionary data containing values for variables a, b, c, and d."],"code":[{"lang":"python","text":"data = {'a': np.arange(50),\n        'c': np.random.randint(0, 50, 50),\n        'd': np.random.randn(50)}\n\ndata['b'] = data['a'] + 10 * np.random.randn(50)\ndata['d'] = np.abs(data['d']) * 100"}]},{"title":"Generate Plot","body":["In this step, we will generate a scatter plot using the data dictionary as input to the scatter() function. We will use the strings corresponding to the a, b, c, and d variables to generate the plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.scatter('a', 'b', c='c', s='d', data=data)\nax.set(xlabel='entry a', ylabel='entry b')\nplt.show()"}]},{"title":"Interpret the Plot","body":["In this step, we will interpret the scatter plot generated in Step 4. The plot shows the relationship between the a and b variables, with the c variable used to determine the color of each point and the d variable used to determine the size of each point. The x-axis represents entry a and the y-axis represents entry b."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-labelling-subplots-with-matplotlib":{"intro":"Matplotlib is a widely used data visualization library in Python. It provides a variety of tools to create different types of plots, including subplots. When creating subplots, it is often helpful to label each plot to make it easier for the reader to understand the information being presented. In this lab, we will learn how to label subplots using different methods provided by Matplotlib.","steps":[{"title":"Import Libraries","body":["The first step is to import the required libraries. We will be using matplotlib.pyplot and matplotlib.transforms to create and transform the subplots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.transforms as mtransforms"}]},{"title":"Create Subplots","body":["Next, we create the subplots using plt.subplot_mosaic. We will create a 3x2 grid of subplots and label them as follows:","• The top-left plot will be labeled as \"a)\" • The bottom-left plot will be labeled as \"b)\" • The top-right and bottom-right plots will be labeled as \"c)\" and \"d)\" respectively."],"code":[{"lang":"python","text":"fig, axs = plt.subplot_mosaic([['a)', 'c)'], ['b)', 'c)'], ['d)', 'd)']], layout='constrained')"}]},{"title":"Label Inside the Axes","body":["The simplest method to label subplots is to put the label inside the axes. We can achieve this by using the ax.text method. We will loop through each subplot and add the label inside the axes using ax.transAxes."],"code":[{"lang":"python","text":"for label, ax in axs.items():\n    # label physical distance in and down:\n    trans = mtransforms.ScaledTranslation(10/72, -5/72, fig.dpi_scale_trans)\n    ax.text(0.0, 1.0, label, transform=ax.transAxes + trans,\n            fontsize='medium', verticalalignment='top', fontfamily='serif',\n            bbox=dict(facecolor='0.7', edgecolor='none', pad=3.0))"}]},{"title":"Label Outside the Axes","body":["We may prefer the labels outside the axes but still aligned with each other. In this case, we use a slightly different transform."],"code":[{"lang":"python","text":"for label, ax in axs.items():\n    # label physical distance to the left and up:\n    trans = mtransforms.ScaledTranslation(-20/72, 7/72, fig.dpi_scale_trans)\n    ax.text(0.0, 1.0, label, transform=ax.transAxes + trans,\n            fontsize='medium', va='bottom', fontfamily='serif')"}]},{"title":"Label with Title","body":["If we want the label to be aligned with the title, we can incorporate it into the title or use the loc keyword argument."],"code":[{"lang":"python","text":"for label, ax in axs.items():\n    ax.set_title('Normal Title', fontstyle='italic')\n    ax.set_title(label, fontfamily='serif', loc='left', fontsize='medium')"}]},{"title":"Display the Subplots","body":["Finally, we display the subplots using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-lasso-demo":{"intro":"In this lab, you will learn how to use the Matplotlib library to create an interactive plot that allows users to select a set of points using a lasso tool. You will also learn how to use a callback function to change the color of the selected points.","steps":[{"title":"Import Libraries","body":["First, import the necessary libraries for the lab. We will be using matplotlib to create the plot and numpy to generate random data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create the Lasso Manager Class","body":["Create the Lasso Manager Class","Next, create the LassoManager class that will handle the lasso functionality. The __init__ method initializes the plot and collection object. The callback method changes the color of the selected points, and the on_press and on_release methods handle the mouse events."],"code":[{"lang":"python","text":"class LassoManager:\n    def __init__(self, ax, data):\n        # The information of whether a point has been selected or not is stored in the\n        # collection's array (0 = out, 1 = in), which then gets colormapped to blue\n        # (out) and red (in).\n        self.collection = RegularPolyCollection(\n            6, sizes=(100,), offset_transform=ax.transData,\n            offsets=data, array=np.zeros(len(data)),\n            clim=(0, 1), cmap=mcolors.ListedColormap([\"tab:blue\", \"tab:red\"]))\n        ax.add_collection(self.collection)\n        canvas = ax.figure.canvas\n        canvas.mpl_connect('button_press_event', self.on_press)\n        canvas.mpl_connect('button_release_event', self.on_release)\n\n    def callback(self, verts):\n        data = self.collection.get_offsets()\n        self.collection.set_array(path.Path(verts).contains_points(data))\n        canvas = self.collection.figure.canvas\n        canvas.draw_idle()\n        del self.lasso\n\n    def on_press(self, event):\n        canvas = self.collection.figure.canvas\n        if event.inaxes is not self.collection.axes or canvas.widgetlock.locked():\n            return\n        self.lasso = Lasso(event.inaxes, (event.xdata, event.ydata), self.callback)\n        canvas.widgetlock(self.lasso)  # acquire a lock on the widget drawing\n\n    def on_release(self, event):\n        canvas = self.collection.figure.canvas\n        if hasattr(self, 'lasso') and canvas.widgetlock.isowner(self.lasso):\n            canvas.widgetlock.release(self.lasso)"}]},{"title":"Create the Plot","body":["Now, use the LassoManager class to create an interactive plot. The np.random.rand function generates random data points that will be plotted."],"code":[{"lang":"python","text":"if __name__ == '__main__':\n    np.random.seed(19680801)\n    ax = plt.figure().add_subplot(\n        xlim=(0, 1), ylim=(0, 1), title='Lasso points using left mouse button')\n    manager = LassoManager(ax, np.random.rand(100, 2))\n    plt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"if __name__ == '__main__':\n    np.random.seed(19680801)\n    ax = plt.figure().add_subplot(\n        xlim=(0, 1), ylim=(0, 1), title='Lasso points using left mouse button')\n    manager = LassoManager(ax, np.random.rand(100, 2))\n    plt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-lasso-selector-demo-sgskip":{"intro":"In this lab, you will learn how to interactively select data points with the lasso tool using Python Matplotlib. You will be plotting a scatter plot and then selecting a few points by drawing a lasso loop around the points on the graph. To draw, just click on the graph, hold, and drag it around the points you need to select.","steps":[{"title":"Import Libraries","body":["Import the necessary libraries, including numpy, Path and LassoSelector."],"code":[{"lang":"python","text":"import numpy as np\nfrom matplotlib.path import Path\nfrom matplotlib.widgets import LassoSelector"}]},{"title":"Create the Selector Class","body":["Create the SelectFromCollection class that will select indices from a Matplotlib collection using LassoSelector."],"code":[{"lang":"python","text":"class SelectFromCollection:\n    \"\"\"\n    Select indices from a matplotlib collection using `LassoSelector`.\n\n    Selected indices are saved in the `ind` attribute. This tool fades out the\n    points that are not part of the selection (i.e., reduces their alpha\n    values). If your collection has alpha < 1, this tool will permanently\n    alter the alpha values.\n\n    Note that this tool selects collection objects based on their *origins*\n    (i.e., `offsets`).\n\n    Parameters\n    ----------\n    ax : `~matplotlib.axes.Axes`\n        Axes to interact with.\n    collection : `matplotlib.collections.Collection` subclass\n        Collection you want to select from.\n    alpha_other : 0 <= float <= 1\n        To highlight a selection, this tool sets all selected points to an\n        alpha value of 1 and non-selected points to *alpha_other*.\n    \"\"\"\n\n    def __init__(self, ax, collection, alpha_other=0.3):\n        self.canvas = ax.figure.canvas\n        self.collection = collection\n        self.alpha_other = alpha_other\n\n        self.xys = collection.get_offsets()\n        self.Npts = len(self.xys)\n\n        # Ensure that we have separate colors for each object\n        self.fc = collection.get_facecolors()\n        if len(self.fc) == 0:\n            raise ValueError('Collection must have a facecolor')\n        elif len(self.fc) == 1:\n            self.fc = np.tile(self.fc, (self.Npts, 1))\n\n        self.lasso = LassoSelector(ax, onselect=self.onselect)\n        self.ind = []\n\n    def onselect(self, verts):\n        path = Path(verts)\n        self.ind = np.nonzero(path.contains_points(self.xys))[0]\n        self.fc[:, -1] = self.alpha_other\n        self.fc[self.ind, -1] = 1\n        self.collection.set_facecolors(self.fc)\n        self.canvas.draw_idle()"}]},{"title":"Create the Scatter Plot","body":["Create a scatter plot using randomly generated data."],"code":[{"lang":"python","text":"np.random.seed(19680801)\ndata = np.random.rand(100, 2)\n\nsubplot_kw = dict(xlim=(0, 1), ylim=(0, 1), autoscale_on=False)\nfig, ax = plt.subplots(subplot_kw=subplot_kw)\npts = ax.scatter(data[:, 0], data[:, 1], s=80)\nselector = SelectFromCollection(ax, pts)"}]},{"title":"Accept the Selected Points","body":["Accept the selected points using the enter key and print them to the console."],"code":[{"lang":"python","text":"def accept(event):\n    if event.key == \"enter\":\n        print(\"Selected points:\")\n        print(selector.xys[selector.ind])\n        selector.disconnect()\n        ax.set_title(\"\")\n        fig.canvas.draw()\n\nfig.canvas.mpl_connect(\"key_press_event\", accept)\nax.set_title(\"Press enter to accept selected points.\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"def accept(event):\n    if event.key == \"enter\":\n        print(\"Selected points:\")\n        print(selector.xys[selector.ind])\n        selector.disconnect()\n        ax.set_title(\"\")\n        fig.canvas.draw()\n\nfig.canvas.mpl_connect(\"key_press_event\", accept)\nax.set_title(\"Press enter to accept selected points.\")\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-python-matplotlib-image-layering-tutorial":{"intro":"This is a step-by-step tutorial on how to layer images using alpha blending with Python Matplotlib.","steps":[{"title":"Import necessary libraries and define a function","body":["Import necessary libraries and define a function","Import the necessary libraries and define a function to create the first image."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\ndef func3(x, y):\n    return (1 - x / 2 + x**5 + y**3) * np.exp(-(x**2 + y**2))"}]},{"title":"Define the x and y variables","body":["Define the x and y variables to create the meshgrid."],"code":[{"lang":"python","text":"dx, dy = 0.05, 0.05\nx = np.arange(-3.0, 3.0, dx)\ny = np.arange(-3.0, 3.0, dy)\nX, Y = np.meshgrid(x, y)"}]},{"title":"Define the extent and create the first image","body":["Define the extent and create the first image","Define the extent and create the first image using the imshow function."],"code":[{"lang":"python","text":"extent = np.min(x), np.max(x), np.min(y), np.max(y)\nZ1 = np.add.outer(range(8), range(8)) % 2  # chessboard\nim1 = plt.imshow(Z1, cmap=plt.cm.gray, interpolation='nearest',\n                 extent=extent)"}]},{"title":"Create the second image","body":["Create the second image using the func3 function and the imshow function."],"code":[{"lang":"python","text":"Z2 = func3(X, Y)\nim2 = plt.imshow(Z2, cmap=plt.cm.viridis, alpha=.9, interpolation='bilinear',\n                 extent=extent)"}]},{"title":"Display the final image","body":["Use the show function to display the final image."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-data-visualization-tutorial":{"intro":"This tutorial introduces the basic usage of Matplotlib library in Python, which is a popular data visualization tool in Python. Matplotlib is a library that allows users to create visualizations such as line plots, scatter plots, bar plots, and many more.","steps":[{"title":"Importing the Required Libraries","body":["Importing the Required Libraries","First, we will import the necessary libraries. We will be using the pyplot module of the matplotlib library to create visualizations."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating a Simple Line Plot","body":["We will create a simple line plot with X-axis values ranging from 0 to 5 and corresponding Y-axis values. We will use the plot function provided by the pyplot module to create the line plot."],"code":[{"lang":"python","text":"# Creating X-axis values\nx = np.arange(0, 5, 0.1)\n\n# Creating Y-axis values\ny = np.sin(x)\n\n# Creating a line plot\nplt.plot(x, y)\n\n# Adding title and labels to the plot\nplt.title('Simple Line Plot')\nplt.xlabel('X-axis')\nplt.ylabel('Y-axis')\n\n# Displaying the plot\nplt.show()"}]},{"title":"Creating a Scatter Plot","body":["We will create a scatter plot with X-axis values ranging from 0 to 5 and corresponding Y-axis values. We will use the scatter function provided by the pyplot module to create the scatter plot."],"code":[{"lang":"python","text":"# Creating X-axis values\nx = np.arange(0, 5, 0.1)\n\n# Creating Y-axis values\ny = np.sin(x)\n\n# Creating a scatter plot\nplt.scatter(x, y)\n\n# Adding title and labels to the plot\nplt.title('Scatter Plot')\nplt.xlabel('X-axis')\nplt.ylabel('Y-axis')\n\n# Displaying the plot\nplt.show()"}]},{"title":"Creating a Bar Plot","body":["We will create a bar plot with X-axis values ranging from 0 to 5 and corresponding Y-axis values. We will use the bar function provided by the pyplot module to create the bar plot."],"code":[{"lang":"python","text":"# Creating X-axis values\nx = np.arange(0, 5, 0.1)\n\n# Creating Y-axis values\ny = np.sin(x)\n\n# Creating a bar plot\nplt.bar(x, y)\n\n# Adding title and labels to the plot\nplt.title('Bar Plot')\nplt.xlabel('X-axis')\nplt.ylabel('Y-axis')\n\n# Displaying the plot\nplt.show()"}]},{"title":"Creating a Pie Chart","body":["We will create a pie chart with five slices representing different data points. We will use the pie function provided by the pyplot module to create the pie chart."],"code":[{"lang":"python","text":"# Creating data for the pie chart\ndata = [10, 20, 30, 25, 15]\n\n# Creating labels for the pie chart\nlabels = ['Data 1', 'Data 2', 'Data 3', 'Data 4', 'Data 5']\n\n# Creating a pie chart\nplt.pie(data, labels=labels)\n\n# Adding title to the plot\nplt.title('Pie Chart')\n\n# Displaying the plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Creating data for the pie chart\ndata = [10, 20, 30, 25, 15]\n\n# Creating labels for the pie chart\nlabels = ['Data 1', 'Data 2', 'Data 3', 'Data 4', 'Data 5']\n\n# Creating a pie chart\nplt.pie(data, labels=labels)\n\n# Adding title to the plot\nplt.title('Pie Chart')\n\n# Displaying the plot\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-a-legend-with-pre-definedels":{"intro":"In data visualization, a legend is a key to interpreting the visual elements of a plot. It helps the viewer to understand the data and the meaning of the visual representation. Matplotlib is a popular Python library for creating data visualizations, including plots with legends. In this tutorial, we will learn how to create a legend with pre-defined labels in Matplotlib.","steps":[{"title":"Importing the Required Libraries","body":["Importing the Required Libraries","We will start by importing the required libraries, which include Matplotlib and NumPy. We use NumPy to generate some fake data for our plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generating the Data","body":["Next, we will generate some fake data to use in our plot. We will create two arrays, a and b, using the NumPy arange function. We then calculate two more arrays, c and d, using the exp function to compute the exponential of a and d as the reverse of c."],"code":[{"lang":"python","text":"# Make some fake data.\na = b = np.arange(0, 3, .02)\nc = np.exp(a)\nd = c[::-1]"}]},{"title":"Creating the Plot","body":["Now we are ready to create our plot. We will use the plot function of Matplotlib to plot three lines on the same graph, each with a pre-defined label. We will use the label parameter to assign the labels to each line."],"code":[{"lang":"python","text":"# Create plots with pre-defined labels.\nfig, ax = plt.subplots()\nax.plot(a, c, 'k--', label='Model length')\nax.plot(a, d, 'k:', label='Data length')\nax.plot(a, c + d, 'k', label='Total message length')"}]},{"title":"Adding the Legend","body":["To add the legend to our plot, we use the legend function of Matplotlib. We pass in the loc parameter to specify the location of the legend, and the shadow parameter to add a shadow effect to the legend. We also use the fontsize parameter to set the font size of the legend."],"code":[{"lang":"python","text":"legend = ax.legend(loc='upper center', shadow=True, fontsize='x-large')"}]},{"title":"Styling the Legend","body":["Finally, we can style the legend to make it more visually appealing. We use the get_frame function to get the frame of the legend, and then use the set_facecolor function to set the background color of the frame."],"code":[{"lang":"python","text":"# Put a nicer background color on the legend.\nlegend.get_frame().set_facecolor('C0')"}]},{"title":"Displaying the Plot","body":["We can now display the plot using the show function of Matplotlib."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-customizing-matplotlib-legends":{"intro":"In this lab, we will explore how to create and customize legends in Matplotlib. Legends are used to explain the meaning of the elements in a chart, including lines, bars, and markers. We will demonstrate how to create legends for specific lines, complex labels, and more complex plots. Finally, we will show how to write custom classes to stylize legends.","steps":[{"title":"Create a legend for specific lines","body":["Create a legend for specific lines","In this step, we will create a legend for specific lines."],"code":[{"lang":"python","text":"# Import necessary libraries\nimport matplotlib.pyplot as plt\nimport numpy as np\n\n# Define data for the chart\nt1 = np.arange(0.0, 2.0, 0.1)\nt2 = np.arange(0.0, 2.0, 0.01)\n\n# Create a plot with multiple lines\nfig, ax = plt.subplots()\nl1, = ax.plot(t2, np.exp(-t2))\nl2, l3 = ax.plot(t2, np.sin(2 * np.pi * t2), '--o', t1, np.log(1 + t1), '.')\nl4, = ax.plot(t2, np.exp(-t2) * np.sin(2 * np.pi * t2), 's-.')\n\n# Create a legend for two of the lines\nax.legend((l2, l4), ('oscillatory', 'damped'), loc='upper right', shadow=True)\n\n# Add labels and title to the chart\nax.set_xlabel('time')\nax.set_ylabel('volts')\nax.set_title('Damped oscillation')\n\n# Display the chart\nplt.show()"}]},{"title":"Plot more complex labels","body":["In this step, we will plot more complex labels."],"code":[{"lang":"python","text":"# Define data for the chart\nx = np.linspace(0, 1)\n\n# Create a chart with multiple lines\nfig, (ax0, ax1) = plt.subplots(2, 1)\nfor n in range(1, 5):\n    ax0.plot(x, x**n, label=f\"{n=}\")\n\n# Create a legend with multiple columns and a title\nleg = ax0.legend(loc=\"upper left\", bbox_to_anchor=[0, 1],\n                 ncols=2, shadow=True, title=\"Legend\", fancybox=True)\nleg.get_title().set_color(\"red\")\n\n# Create a chart with multiple lines and markers\nax1.plot(x, x**2, label=\"multi\\nline\")\nhalf_pi = np.linspace(0, np.pi / 2)\nax1.plot(np.sin(half_pi), np.cos(half_pi), label=r\"$\\frac{1}{2}\\pi$\")\nax1.plot(x, 2**(x**2), label=\"$2^{x^2}$\")\n\n# Create a legend with a shadow\nax1.legend(shadow=True, fancybox=True)\n\n# Display the chart\nplt.show()"}]},{"title":"Attach legends to more complex plots","body":["Attach legends to more complex plots","In this step, we will attach legends to more complex plots."],"code":[{"lang":"python","text":"# Define data for the chart\nfig, axs = plt.subplots(3, 1, layout=\"constrained\")\ntop_ax, middle_ax, bottom_ax = axs\n\n# Create a bar chart with multiple bars\ntop_ax.bar([0, 1, 2], [0.2, 0.3, 0.1], width=0.4, label=\"Bar 1\",\n           align=\"center\")\ntop_ax.bar([0.5, 1.5, 2.5], [0.3, 0.2, 0.2], color=\"red\", width=0.4,\n           label=\"Bar 2\", align=\"center\")\ntop_ax.legend()\n\n# Create an error bar chart with multiple errors\nmiddle_ax.errorbar([0, 1, 2], [2, 3, 1], xerr=0.4, fmt=\"s\", label=\"test 1\")\nmiddle_ax.errorbar([0, 1, 2], [3, 2, 4], yerr=0.3, fmt=\"o\", label=\"test 2\")\nmiddle_ax.errorbar([0, 1, 2], [1, 1, 3], xerr=0.4, yerr=0.3, fmt=\"^\",\n                   label=\"test 3\")\nmiddle_ax.legend()\n\n# Create a stem chart with a legend\nbottom_ax.stem([0.3, 1.5, 2.7], [1, 3.6, 2.7], label=\"stem test\")\nbottom_ax.legend()\n\n# Display the chart\nplt.show()"}]},{"title":"Create legend entries with more than one legend key","body":["Create legend entries with more than one legend key","In this step, we will create legend entries with more than one legend key."],"code":[{"lang":"python","text":"# Define data for the chart\nfig, (ax1, ax2) = plt.subplots(2, 1, layout='constrained')\np1 = ax1.scatter([1], [5], c='r', marker='s', s=100)\np2 = ax1.scatter([3], [2], c='b', marker='o', s=100)\np3, = ax1.plot([1, 5], [4, 4], 'm-d')\n\n# Create a legend with two keys for one entry\nl = ax1.legend([(p1, p3), p2], ['two keys', 'one key'], scatterpoints=1,\n               numpoints=1, handler_map={tuple: HandlerTuple(ndivide=None)})\n\n# Create two bar charts on top of each other and change the padding between the legend keys\nx_left = [1, 2, 3]\ny_pos = [1, 3, 2]\ny_neg = [2, 1, 4]\nrneg = ax2.bar(x_left, y_neg, width=0.5, color='w', hatch='///', label='-1')\nrpos = ax2.bar(x_left, y_pos, width=0.5, color='k', label='+1')\n\n# Treat each legend entry differently by using specific `HandlerTuple`s\nl = ax2.legend([(rpos, rneg), (rneg, rpos)], ['pad!=0', 'pad=0'],\n               handler_map={(rpos, rneg): HandlerTuple(ndivide=None),\n                            (rneg, rpos): HandlerTuple(ndivide=None, pad=0.)})\n\n# Display the chart\nplt.show()"}]},{"title":"Write custom classes to stylize legends","body":["Write custom classes to stylize legends","In this step, we will write custom classes to stylize legends."],"code":[{"lang":"python","text":"# Define data for the chart\nclass HandlerDashedLines(HandlerLineCollection):\n    \"\"\"\n    Custom Handler for LineCollection instances.\n    \"\"\"\n    def create_artists(self, legend, orig_handle,\n                       xdescent, ydescent, width, height, fontsize, trans):\n        # figure out how many lines there are\n        numlines = len(orig_handle.get_segments())\n        xdata, xdata_marker = self.get_xdata(legend, xdescent, ydescent,\n                                             width, height, fontsize)\n        leglines = []\n        # divide the vertical space where the lines will go\n        # into equal parts based on the number of lines\n        ydata = np.full_like(xdata, height / (numlines + 1))\n        # for each line, create the line at the proper location\n        # and set the dash pattern\n        for i in range(numlines):\n            legline = Line2D(xdata, ydata * (numlines - i) - ydescent)\n            self.update_prop(legline, orig_handle, legend)\n            # set color, dash pattern, and linewidth to that\n            # of the lines in linecollection\n            try:\n                color = orig_handle.get_colors()[i]\n            except IndexError:\n                color = orig_handle.get_colors()[0]\n            try:\n                dashes = orig_handle.get_dashes()[i]\n            except IndexError:\n                dashes = orig_handle.get_dashes()[0]\n            try:\n                lw = orig_handle.get_linewidths()[i]\n            except IndexError:\n                lw = orig_handle.get_linewidths()[0]\n            if dashes[1] is not None:\n                legline.set_dashes(dashes[1])\n            legline.set_color(color)\n            legline.set_transform(trans)\n            legline.set_linewidth(lw)\n            leglines.append(legline)\n        return leglines\n\n# Create a chart with multiple lines\nx = np.linspace(0, 5, 100)\nfig, ax = plt.subplots()\ncolors = plt.rcParams['axes.prop_cycle'].by_key()['color'][:5]\nstyles = ['solid', 'dashed', 'dashed', 'dashed', 'solid']\nfor i, color, style in zip(range(5), colors, styles):"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Define data for the chart\nclass HandlerDashedLines(HandlerLineCollection):\n    \"\"\"\n    Custom Handler for LineCollection instances.\n    \"\"\"\n    def create_artists(self, legend, orig_handle,\n                       xdescent, ydescent, width, height, fontsize, trans):\n        # figure out how many lines there are\n        numlines = len(orig_handle.get_segments())\n        xdata, xdata_marker = self.get_xdata(legend, xdescent, ydescent,\n                                             width, height, fontsize)\n        leglines = []\n        # divide the vertical space where the lines will go\n        # into equal parts based on the number of lines\n        ydata = np.full_like(xdata, height / (numlines + 1))\n        # for each line, create the line at the proper location\n        # and set the dash pattern\n        for i in range(numlines):\n            legline = Line2D(xdata, ydata * (numlines - i) - ydescent)\n            self.update_prop(legline, orig_handle, legend)\n            # set color, dash pattern, and linewidth to that\n            # of the lines in linecollection\n            try:\n                color = orig_handle.get_colors()[i]\n            except IndexError:\n                color = orig_handle.get_colors()[0]\n            try:\n                dashes = orig_handle.get_dashes()[i]\n            except IndexError:\n                dashes = orig_handle.get_dashes()[0]\n            try:\n                lw = orig_handle.get_linewidths()[i]\n            except IndexError:\n                lw = orig_handle.get_linewidths()[0]\n            if dashes[1] is not None:\n                legline.set_dashes(dashes[1])\n            legline.set_color(color)\n            legline.set_transform(trans)\n            legline.set_linewidth(lw)\n            leglines.append(legline)\n        return leglines\n\n# Create a chart with multiple lines\nx = np.linspace(0, 5, 100)\nfig, ax = plt.subplots()\ncolors = plt.rcParams['axes.prop_cycle'].by_key()['color'][:5]\nstyles = ['solid', 'dashed', 'dashed', 'dashed', 'solid']\nfor i, color, style in zip(range(5), colors, styles):"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-legend-toggling-tutorial":{"intro":"In this lab, we will learn how to enable picking on the legend to toggle the original line on and off using Python Matplotlib.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries, which are NumPy and Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Prepare Data","body":["We will generate two sine waves with different frequencies using NumPy."],"code":[{"lang":"python","text":"t = np.linspace(0, 1)\ny1 = 2 * np.sin(2*np.pi*t)\ny2 = 4 * np.sin(2*np.pi*2*t)"}]},{"title":"Create Figure and Axes","body":["We will create a figure and axes using Matplotlib and set the title of the plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.set_title('Click on legend line to toggle line on/off')"}]},{"title":"Create Lines and Legend","body":["We will create two lines and a legend using Matplotlib."],"code":[{"lang":"python","text":"line1, = ax.plot(t, y1, lw=2, label='1 Hz')\nline2, = ax.plot(t, y2, lw=2, label='2 Hz')\nleg = ax.legend(fancybox=True, shadow=True)"}]},{"title":"Map Legend Lines to Original Lines","body":["Map Legend Lines to Original Lines","We will map the legend lines to the original lines using a dictionary."],"code":[{"lang":"python","text":"lines = [line1, line2]\nlined = {}  # Will map legend lines to original lines.\nfor legline, origline in zip(leg.get_lines(), lines):\n    legline.set_picker(True)  # Enable picking on the legend line.\n    lined[legline] = origline"}]},{"title":"Define the On Pick Event Function","body":["Define the On Pick Event Function","We will define the on pick event function that will toggle the visibility of the original line corresponding to the legend proxy line."],"code":[{"lang":"python","text":"def on_pick(event):\n    # On the pick event, find the original line corresponding to the legend\n    # proxy line, and toggle its visibility.\n    legline = event.artist\n    origline = lined[legline]\n    visible = not origline.get_visible()\n    origline.set_visible(visible)\n    # Change the alpha on the line in the legend, so we can see what lines\n    # have been toggled.\n    legline.set_alpha(1.0 if visible else 0.2)\n    fig.canvas.draw()"}]},{"title":"Connect the On Pick Event Function to the Canvas","body":["Connect the On Pick Event Function to the Canvas","We will connect the on pick event function to the canvas."],"code":[{"lang":"python","text":"fig.canvas.mpl_connect('pick_event', on_pick)"}]},{"title":"Show the Plot","body":["We will show the plot using Matplotlib."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-efficient-line-plotting-with-matplotlib":{"intro":"In this tutorial, we will learn how to use the LineCollection function in Matplotlib to efficiently draw multiple lines at once. We will see how to plot multiple lines with different colors and styles, and how to use a masked array to mask some values. We will also learn how to use the ScalarMappable.set_array function to map an array of values to colors.","steps":[{"title":"Import Libraries","body":["Before we start, we need to import the necessary libraries. We will use matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["Next, we need to create the data that we will use to plot the lines. We will use numpy to create a 2D array of x and y values."],"code":[{"lang":"python","text":"x = np.arange(100)\nys = x[:50, np.newaxis] + x[np.newaxis, :]"}]},{"title":"Create Line Collection","body":["Now, we can create a LineCollection object with the LineCollection function. We can set the linewidths, colors, and linestyle parameters to customize the appearance of the lines."],"code":[{"lang":"python","text":"colors = plt.rcParams['axes.prop_cycle'].by_key()['color']\n\nsegs = np.zeros((50, 100, 2))\nsegs[:, :, 1] = ys\nsegs[:, :, 0] = x\n\nsegs = np.ma.masked_where((segs > 50) & (segs < 60), segs)\n\nline_segments = LineCollection(segs, linewidths=(0.5, 1, 1.5, 2),\n                               colors=colors, linestyle='solid')"}]},{"title":"Create Plot","body":["We can now create a plot using matplotlib and add the LineCollection object to the plot using the add_collection method of the Axes object."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.set_xlim(x.min(), x.max())\nax.set_ylim(ys.min(), ys.max())\n\nax.add_collection(line_segments)\nax.set_title('Line collection with masked arrays')\nplt.show()"}]},{"title":"Map Colors to Values","body":["We can also map an array of values to colors using the ScalarMappable.set_array function. We will create a new set of data and a new LineCollection object with the array parameter set to the x values. We can then use the colorbar method of the Figure object to add a colorbar to the plot."],"code":[{"lang":"python","text":"N = 50\nx = np.arange(N)\nys = [x + i for i in x]\nsegs = [np.column_stack([x, y]) for y in ys]\n\nfig, ax = plt.subplots()\nax.set_xlim(np.min(x), np.max(x))\nax.set_ylim(np.min(ys), np.max(ys))\n\nline_segments = LineCollection(segs, array=x,\n                               linewidths=(0.5, 1, 1.5, 2),\n                               linestyles='solid')\nax.add_collection(line_segments)\naxcb = fig.colorbar(line_segments)\naxcb.set_label('Line Number')\nax.set_title('Line Collection with mapped colors')\nplt.sci(line_segments)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"N = 50\nx = np.arange(N)\nys = [x + i for i in x]\nsegs = [np.column_stack([x, y]) for y in ys]\n\nfig, ax = plt.subplots()\nax.set_xlim(np.min(x), np.max(x))\nax.set_ylim(np.min(ys), np.max(ys))\n\nline_segments = LineCollection(segs, array=x,\n                               linewidths=(0.5, 1, 1.5, 2),\n                               linestyles='solid')\nax.add_collection(line_segments)\naxcb = fig.colorbar(line_segments)\naxcb.set_label('Line Number')\nax.set_title('Line Collection with mapped colors')\nplt.sci(line_segments)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-customizing-dashed-line-styles-in-matplotlib":{"intro":"In this lab, we will learn how to customize the dashed line styles in Matplotlib. We will cover how to modify the dash sequence using .Line2D.set_dashes(), configure the dash style using a property_cycle, and set other attributes of the dash using relevant methods like ~.Line2D.set_dash_capstyle(), ~.Line2D.set_dash_joinstyle(), and ~.Line2D.set_gapcolor().","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","First, we need to import the necessary libraries. We will be using Matplotlib and NumPy in this lab."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create data for plotting","body":["Next, we need to create some data to plot. In this lab, we will be using the sine function to create our data. We will generate 500 evenly spaced points between 0 and 10 and calculate the sine of each point using the np.sin() function."],"code":[{"lang":"python","text":"x = np.linspace(0, 10, 500)\ny = np.sin(x)"}]},{"title":"Set the line width","body":["We can set the line width for all the lines in the plot using the plt.rc() function. In this lab, we will be setting the line width to 2.5."],"code":[{"lang":"python","text":"plt.rc('lines', linewidth=2.5)"}]},{"title":"Create the plot","body":["Now, we can create the plot using the plt.subplots() function. We will also create three lines using the ax.plot() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\n# Using set_dashes() and set_capstyle() to modify dashing of an existing line.\nline1, = ax.plot(x, y, label='Using set_dashes() and set_dash_capstyle()')\nline1.set_dashes([2, 2, 10, 2])  # 2pt line, 2pt break, 10pt line, 2pt break.\nline1.set_dash_capstyle('round')\n\n# Using plot(..., dashes=...) to set the dashing when creating a line.\nline2, = ax.plot(x, y - 0.2, dashes=[6, 2], label='Using the dashes parameter')\n\n# Using plot(..., dashes=..., gapcolor=...) to set the dashing and\n# alternating color when creating a line.\nline3, = ax.plot(x, y - 0.4, dashes=[4, 4], gapcolor='tab:pink',\n                 label='Using the dashes and gapcolor parameters')\n\nax.legend(handlelength=4)\nplt.show()"}]},{"title":"Modify the dash sequence using .Line2D.set_dashes()","body":["Modify the dash sequence using .Line2D.set_dashes()","We can modify the dash sequence using .Line2D.set_dashes(). In this example, we modify the dash sequence for line1 to create a dash pattern of 2pt line, 2pt break, 10pt line, and 2pt break. We also set the cap style to 'round' using line1.set_dash_capstyle()."],"code":[{"lang":"python","text":"line1, = ax.plot(x, y, label='Using set_dashes() and set_dash_capstyle()')\nline1.set_dashes([2, 2, 10, 2])  # 2pt line, 2pt break, 10pt line, 2pt break.\nline1.set_dash_capstyle('round')"}]},{"title":"Set the dash style using a property_cycle","body":["Set the dash style using a property_cycle","We can configure the dash style using a property_cycle. This can be done by passing a list of dash sequences using the keyword _dashes_ to the cycler. In this example, we will not be using this method."],"code":[]},{"title":"Set other attributes of the dash using relevant methods","body":["Set other attributes of the dash using relevant methods","Other attributes of the dash may also be set using relevant methods like ~.Line2D.set_dash_joinstyle(), ~.Line2D.set_dash_joinstyle(), and ~.Line2D.set_gapcolor(). In this example, we will be using the dashes and gapcolor parameters to set the dash sequence and alternating color for line3."],"code":[{"lang":"python","text":"line3, = ax.plot(x, y - 0.4, dashes=[4, 4], gapcolor='tab:pink',\n                 label='Using the dashes and gapcolor parameters')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"line3, = ax.plot(x, y - 0.4, dashes=[4, 4], gapcolor='tab:pink',\n                 label='Using the dashes and gapcolor parameters')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-ticked-patheffect":{"intro":"In this lab, we will learn how to add ticks along a line in Matplotlib using Ticked Patheffect. Ticks can be added to mark one side as a barrier and you can control the angle, spacing, and length of the ticks. Ticks will also appear appropriately in the legend.","steps":[{"title":"Import Libraries and Generate Data","body":["Import Libraries and Generate Data","We will first import the necessary libraries and generate some data for plotting."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib import patheffects\n\n# Generate data\nnx = 101\nx = np.linspace(0.0, 1.0, nx)\ny = 0.3*np.sin(x*8) + 0.4"}]},{"title":"Plot a Straight Line with Ticked Patheffect","body":["Plot a Straight Line with Ticked Patheffect","We will now plot a straight diagonal line with ticked patheffect."],"code":[{"lang":"python","text":"# Plot a straight diagonal line with ticked style path\nfig, ax = plt.subplots(figsize=(6, 6))\nax.plot([0, 1], [0, 1], label=\"Line\",\n        path_effects=[patheffects.withTickedStroke(spacing=7, angle=135)])"}]},{"title":"Plot a Curved Line with Ticked Patheffect","body":["Plot a Curved Line with Ticked Patheffect","We will now plot a curved line with ticked patheffect."],"code":[{"lang":"python","text":"# Plot a curved line with ticked style path\nax.plot(x, y, label=\"Curve\", path_effects=[patheffects.withTickedStroke()])\n\nax.legend()\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Plot a curved line with ticked style path\nax.plot(x, y, label=\"Curve\", path_effects=[patheffects.withTickedStroke()])\n\nax.legend()\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-plot-3d-parametric-curves-with-matplotlib":{"intro":"This lab will demonstrate how to plot a parametric curve in 3D using Matplotlib. The curve will be defined by three equations:","steps":[{"title":"Import necessary libraries","body":["We will begin by importing the necessary libraries: Matplotlib and NumPy. Matplotlib will be used to create the 3D plot, and NumPy will be used to generate the values for x, y, and z."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a 3D plot","body":["Next, we will create a 3D plot using Matplotlib. We will also create an axis object to add labels and legends to the plot."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')"}]},{"title":"Define the values for x, y, and z","body":["Define the values for x, y, and z","We will generate the values for x, y, and z using NumPy. We will first define the range of values for theta and z. Then, we will use these values to generate the values for r, x, and y."],"code":[{"lang":"python","text":"theta = np.linspace(-4 * np.pi, 4 * np.pi, 100)\nz = np.linspace(-2, 2, 100)\nr = z**2 + 1\nx = r * np.sin(theta)\ny = r * np.cos(theta)"}]},{"title":"Plot the parametric curve","body":["Now that we have generated the values for x, y, and z, we can plot the parametric curve using the plot() method in Matplotlib."],"code":[{"lang":"python","text":"ax.plot(x, y, z, label='parametric curve')"}]},{"title":"Add labels and legends to the plot","body":["Add labels and legends to the plot","Finally, we will add labels and legends to the plot using the legend() method."],"code":[{"lang":"python","text":"ax.legend()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-line-styles":{"intro":"Matplotlib is a powerful data visualization tool for Python. One of its features is the ability to create custom line styles for plots. In this lab, we will learn how to create and use different line styles in Matplotlib.","steps":[{"title":"Import the required libraries","body":["To use Matplotlib, we first need to import the library. We will also import the NumPy library to generate some sample data for our plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define line styles","body":["There are different ways to define line styles in Matplotlib. We can use predefined styles such as 'solid', 'dashed', 'dotted', and 'dashdot'. We can also define custom line styles using a dash tuple."],"code":[{"lang":"python","text":"linestyle_str = [\n     ('solid', 'solid'),      # Same as (0, ()) or '-'\n     ('dotted', 'dotted'),    # Same as (0, (1, 1)) or ':'\n     ('dashed', 'dashed'),    # Same as '--'\n     ('dashdot', 'dashdot')]  # Same as '-.'\n\nlinestyle_tuple = [\n     ('loosely dotted',        (0, (1, 10))),\n     ('dotted',                (0, (1, 1))),\n     ('densely dotted',        (0, (1, 1))),\n     ('long dash with offset', (5, (10, 3))),\n     ('loosely dashed',        (0, (5, 10))),\n     ('dashed',                (0, (5, 5))),\n     ('densely dashed',        (0, (5, 1))),\n\n     ('loosely dashdotted',    (0, (3, 10, 1, 10))),\n     ('dashdotted',            (0, (3, 5, 1, 5))),\n     ('densely dashdotted',    (0, (3, 1, 1, 1))),\n\n     ('dashdotdotted',         (0, (3, 5, 1, 5, 1, 5))),\n     ('loosely dashdotdotted', (0, (3, 10, 1, 10, 1, 10))),\n     ('densely dashdotdotted', (0, (3, 1, 1, 1, 1, 1)))]"}]},{"title":"Create a function to plot line styles","body":["Create a function to plot line styles","We can create a function to plot the different line styles. The function takes an axis object, a list of line styles, and a title as input parameters."],"code":[{"lang":"python","text":"def plot_linestyles(ax, linestyles, title):\n    X, Y = np.linspace(0, 100, 10), np.zeros(10)\n    yticklabels = []\n\n    for i, (name, linestyle) in enumerate(linestyles):\n        ax.plot(X, Y+i, linestyle=linestyle, linewidth=1.5, color='black')\n        yticklabels.append(name)\n\n    ax.set_title(title)\n    ax.set(ylim=(-0.5, len(linestyles)-0.5),\n           yticks=np.arange(len(linestyles)),\n           yticklabels=yticklabels)\n    ax.tick_params(left=False, bottom=False, labelbottom=False)\n    ax.spines[:].set_visible(False)\n\n    for i, (name, linestyle) in enumerate(linestyles):\n        ax.annotate(repr(linestyle),\n                    xy=(0.0, i), xycoords=ax.get_yaxis_transform(),\n                    xytext=(-6, -12), textcoords='offset points',\n                    color=\"blue\", fontsize=8, ha=\"right\", family=\"monospace\")"}]},{"title":"Create the plot","body":["We can create the plot by calling the plot_linestyles function for each set of line styles."],"code":[{"lang":"python","text":"fig, (ax0, ax1) = plt.subplots(2, 1, figsize=(10, 8), height_ratios=[1, 3])\n\nplot_linestyles(ax0, linestyle_str[::-1], title='Named linestyles')\nplot_linestyles(ax1, linestyle_tuple[::-1], title='Parametrized linestyles')\n\nplt.tight_layout()\nplt.show()"}]},{"title":"Interpret the plot","body":["The resulting plot shows the different line styles. The top plot shows named line styles while the bottom plot shows parametrized line styles. The annotations on the right side show the dash tuples used for each line style."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-logarithmic-bar-chart":{"intro":"In this lab, we will learn how to create a logarithmic bar chart using Python Matplotlib library. A logarithmic bar chart is useful when the values of the dataset are very different in size, and we want to visualize them in a more balanced way.","steps":[{"title":"Importing Libraries","body":["First, we need to import the necessary libraries. In this case, we will be using the matplotlib.pyplot and numpy libraries. The pyplot library will allow us to create our bar chart, and the numpy library will help us to manipulate the data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Defining the Data","body":["Next, we need to define the data that we want to use for our bar chart. In this example, we will be using a tuple of tuples, where each inner tuple contains two values. The first value represents the x-axis value, and the second value represents the y-axis value."],"code":[{"lang":"python","text":"data = ((3, 1000), (10, 3), (100, 30), (500, 800), (50, 1))"}]},{"title":"Creating the Bar Chart","body":["Now we are ready to create our bar chart. We will start by defining some variables that will help us to set the width of the bars and their position on the x-axis.","Next, we will create a figure and an axis object using the subplots() method. Then, we will use a for loop to iterate through each value in our dataset and create a bar for each one.","We set the bottom parameter to 0.001 to avoid having any bars with a height of 0, which is not compatible with a logarithmic scale."],"code":[{"lang":"python","text":"dim = len(data[0])\nw = 0.75\ndimw = w / dim"},{"lang":"python","text":"fig, ax = plt.subplots()\nx = np.arange(len(data))\nfor i in range(len(data[0])):\n    y = [d[i] for d in data]\n    b = ax.bar(x + i * dimw, y, dimw, bottom=0.001)"}]},{"title":"Customizing the Chart","body":["We can customize the appearance of our chart by adding labels to the x-axis and y-axis, and by setting the scale of the y-axis to logarithmic."],"code":[{"lang":"python","text":"ax.set_xticks(x + dimw / 2, labels=map(str, x))\nax.set_yscale('log')\n\nax.set_xlabel('x')\nax.set_ylabel('y')"}]},{"title":"Displaying the Chart","body":["Finally, we can display our chart using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-logarithmic-axis-plotting":{"intro":"This step-by-step tutorial will guide you through the process of creating plots with logarithmic axes using Python Matplotlib. This tutorial will cover the following topics:","steps":[{"title":"Semilogy Plot","body":["The semilogy plot is a plot with a logarithmic scale on the y-axis. It is useful for visualizing data that has a large range of values."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Data for plotting\nt = np.arange(0.01, 20.0, 0.01)\n\n# Create figure\nfig, ax1 = plt.subplots()\n\n# Plot data on semilogy plot\nax1.semilogy(t, np.exp(-t / 5.0))\n\n# Add title and grid to plot\nax1.set(title='Semilogy Plot')\nax1.grid()\n\n# Display plot\nplt.show()"}]},{"title":"Semilogx Plot","body":["The semilogx plot is a plot with a logarithmic scale on the x-axis. It is useful for visualizing data that has a large range of values on the x-axis."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Data for plotting\nt = np.arange(0.01, 20.0, 0.01)\n\n# Create figure\nfig, ax2 = plt.subplots()\n\n# Plot data on semilogx plot\nax2.semilogx(t, np.sin(2 * np.pi * t))\n\n# Add title and grid to plot\nax2.set(title='Semilogx Plot')\nax2.grid()\n\n# Display plot\nplt.show()"}]},{"title":"Loglog Plot","body":["The loglog plot is a plot with a logarithmic scale on both the x-axis and y-axis. It is useful for visualizing data that has a large range of values on both axes."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Data for plotting\nt = np.arange(0.01, 20.0, 0.01)\n\n# Create figure\nfig, ax3 = plt.subplots()\n\n# Plot data on loglog plot\nax3.loglog(t, 20 * np.exp(-t / 10.0))\n\n# Set x-axis scale to base 2\nax3.set_xscale('log', base=2)\n\n# Add title and grid to plot\nax3.set(title='Loglog Plot')\nax3.grid()\n\n# Display plot\nplt.show()"}]},{"title":"Errorbars Plot","body":["The errorbars plot is a plot that shows error bars for each data point. If a data point has a negative value, it will be clipped to 0.1."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Data for plotting\nx = 10.0**np.linspace(0.0, 2.0, 20)\ny = x**2.0\n\n# Create figure\nfig, ax4 = plt.subplots()\n\n# Set x-axis and y-axis to logarithmic scale\nax4.set_xscale(\"log\", nonpositive='clip')\nax4.set_yscale(\"log\", nonpositive='clip')\n\n# Plot data with error bars\nax4.errorbar(x, y, xerr=0.1 * x, yerr=5.0 + 0.75 * y)\n\n# Set title and y-axis limit\nax4.set(title='Errorbars Plot')\nax4.set_ylim(bottom=0.1)\n\n# Display plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Data for plotting\nx = 10.0**np.linspace(0.0, 2.0, 20)\ny = x**2.0\n\n# Create figure\nfig, ax4 = plt.subplots()\n\n# Set x-axis and y-axis to logarithmic scale\nax4.set_xscale(\"log\", nonpositive='clip')\nax4.set_yscale(\"log\", nonpositive='clip')\n\n# Plot data with error bars\nax4.errorbar(x, y, xerr=0.1 * x, yerr=5.0 + 0.75 * y)\n\n# Set title and y-axis limit\nax4.set(title='Errorbars Plot')\nax4.set_ylim(bottom=0.1)\n\n# Display plot\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-logit-scale-plotting":{"intro":"In this lab, we will learn how to create plots with logit axes in Matplotlib. Logit axes are commonly used in probability plots to represent the cumulative distribution function (CDF) of a distribution. We will use the math, numpy, and matplotlib.pyplot libraries for this lab.","steps":[{"title":"Import the necessary libraries and set up the data","body":["Import the necessary libraries and set up the data","We will import the math, numpy, and matplotlib.pyplot libraries and set up the data for the plots."],"code":[{"lang":"python","text":"import math\nimport numpy as np\nimport matplotlib.pyplot as plt\n\nxmax = 10\nx = np.linspace(-xmax, xmax, 10000)\ncdf_norm = [math.erf(w / np.sqrt(2)) / 2 + 1 / 2 for w in x]\ncdf_laplacian = np.where(x < 0, 1 / 2 * np.exp(x), 1 - 1 / 2 * np.exp(-x))\ncdf_cauchy = np.arctan(x) / np.pi + 1 / 2"}]},{"title":"Create a plot with logit scale and standard notation","body":["Create a plot with logit scale and standard notation","We will create a plot with logit scale and standard notation. This can be done by setting the y-axis scale to logit using set_yscale(\"logit\") and setting the y-axis limits using set_ylim(). We will also plot the cumulative distribution functions for the normal, Laplacian, and Cauchy distributions using plot() and add a legend using legend()."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=1, ncols=1, figsize=(6.4, 4.8))\n\naxs.plot(x, cdf_norm, label=r\"$\\mathcal{N}$\")\naxs.plot(x, cdf_laplacian, label=r\"$\\mathcal{L}$\")\naxs.plot(x, cdf_cauchy, label=\"Cauchy\")\naxs.set_yscale(\"logit\")\naxs.set_ylim(1e-5, 1 - 1e-5)\naxs.legend()\naxs.grid()\n\nplt.show()"}]},{"title":"Create a plot with logit scale and survival notation","body":["Create a plot with logit scale and survival notation","We will create a plot with logit scale and survival notation. This can be done by setting the y-axis scale to logit and setting the one_half parameter to \"1/2\" and use_overline parameter to True using set_yscale(\"logit\", one_half=\"1/2\", use_overline=True)\". We will also plot the cumulative distribution functions for the normal, Laplacian, and Cauchy distributions using plot() and add a legend using legend()."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=1, ncols=1, figsize=(6.4, 4.8))\n\naxs.plot(x, cdf_norm, label=r\"$\\mathcal{N}$\")\naxs.plot(x, cdf_laplacian, label=r\"$\\mathcal{L}$\")\naxs.plot(x, cdf_cauchy, label=\"Cauchy\")\naxs.set_yscale(\"logit\", one_half=\"1/2\", use_overline=True)\naxs.set_ylim(1e-5, 1 - 1e-5)\naxs.legend()\naxs.grid()\n\nplt.show()"}]},{"title":"Create a plot with linear scale","body":["Create a plot with linear scale","We will create a plot with linear scale. This can be done by simply plotting the cumulative distribution functions for the normal, Laplacian, and Cauchy distributions using plot() and add a legend using legend()."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=1, ncols=1, figsize=(6.4, 4.8))\n\naxs.plot(x, cdf_norm, label=r\"$\\mathcal{N}$\")\naxs.plot(x, cdf_laplacian, label=r\"$\\mathcal{L}$\")\naxs.plot(x, cdf_cauchy, label=\"Cauchy\")\naxs.legend()\naxs.grid()\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, axs = plt.subplots(nrows=1, ncols=1, figsize=(6.4, 4.8))\n\naxs.plot(x, cdf_norm, label=r\"$\\mathcal{N}$\")\naxs.plot(x, cdf_laplacian, label=r\"$\\mathcal{L}$\")\naxs.plot(x, cdf_cauchy, label=\"Cauchy\")\naxs.legend()\naxs.grid()\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-matplotlib-logo-with-python":{"intro":"In this lab, you will learn how to create the Matplotlib logo using Python. The Matplotlib library is a popular data visualization tool for Python and is widely used in scientific computing.","steps":[{"title":"Importing the Required Libraries","body":["Importing the Required Libraries","In this step, we will import the necessary libraries, including Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Defining the Constants","body":["In this step, we will define some constants, including the color of the logo and the font."],"code":[{"lang":"python","text":"MPL_BLUE = '#11557c'\n\ndef get_font_properties():\n    # The original font is Calibri, if that is not installed, we fall back\n    # to Carlito, which is metrically equivalent.\n    if 'Calibri' in matplotlib.font_manager.findfont('Calibri:bold'):\n        return matplotlib.font_manager.FontProperties(family='Calibri',\n                                                      weight='bold')\n    if 'Carlito' in matplotlib.font_manager.findfont('Carlito:bold'):\n        print('Original font not found. Falling back to Carlito. '\n              'The logo text will not be in the correct font.')\n        return matplotlib.font_manager.FontProperties(family='Carlito',\n                                                      weight='bold')\n    print('Original font not found. '\n          'The logo text will not be in the correct font.')\n    return None"}]},{"title":"Creating the Icon Axes","body":["In this step, we will create a polar axis containing the Matplotlib radar plot."],"code":[{"lang":"python","text":"def create_icon_axes(fig, ax_position, lw_bars, lw_grid, lw_border, rgrid):\n    \"\"\"\n    Create a polar axes containing the matplotlib radar plot.\n\n    Parameters\n    ----------\n    fig : matplotlib.figure.Figure\n        The figure to draw into.\n    ax_position : (float, float, float, float)\n        The position of the created Axes in figure coordinates as\n        (x, y, width, height).\n    lw_bars : float\n        The linewidth of the bars.\n    lw_grid : float\n        The linewidth of the grid.\n    lw_border : float\n        The linewidth of the Axes border.\n    rgrid : array-like\n        Positions of the radial grid.\n\n    Returns\n    -------\n    ax : matplotlib.axes.Axes\n        The created Axes.\n    \"\"\"\n    with plt.rc_context({'axes.edgecolor': MPL_BLUE,\n                         'axes.linewidth': lw_border}):\n        ax = fig.add_axes(ax_position, projection='polar')\n        ax.set_axisbelow(True)\n\n        N = 7\n        arc = 2. * np.pi\n        theta = np.arange(0.0, arc, arc / N)\n        radii = np.array([2, 6, 8, 7, 4, 5, 8])\n        width = np.pi / 4 * np.array([0.4, 0.4, 0.6, 0.8, 0.2, 0.5, 0.3])\n        bars = ax.bar(theta, radii, width=width, bottom=0.0, align='edge',\n                      edgecolor='0.3', lw=lw_bars)\n        for r, bar in zip(radii, bars):\n            color = *cm.jet(r / 10.)[:3], 0.6  # color from jet with alpha=0.6\n            bar.set_facecolor(color)\n\n        ax.tick_params(labelbottom=False, labeltop=False,\n                       labelleft=False, labelright=False)\n\n        ax.grid(lw=lw_grid, color='0.9')\n        ax.set_rmax(9)\n        ax.set_yticks(rgrid)"}]},{"title":"Creating the Text Axes","body":["In this step, we will create an axis in _fig_ that contains 'matplotlib' as text."],"code":[{"lang":"python","text":"def create_text_axes(fig, height_px):\n    \"\"\"Create an Axes in *fig* that contains 'matplotlib' as Text.\"\"\"\n    ax = fig.add_axes((0, 0, 1, 1))\n    ax.set_aspect(\"equal\")\n    ax.set_axis_off()\n\n    path = TextPath((0, 0), \"matplotlib\", size=height_px * 0.8,\n                    prop=get_font_properties())\n\n    angle = 4.25  # degrees\n    trans = mtrans.Affine2D().skew_deg(angle, 0)\n\n    patch = PathPatch(path, transform=trans + ax.transData, color=MPL_BLUE,\n                      lw=0)\n    ax.add_patch(patch)\n    ax.autoscale()"}]},{"title":"Creating the Logo","body":["In this step, we will create the full figure with the Matplotlib logo."],"code":[{"lang":"python","text":"def make_logo(height_px, lw_bars, lw_grid, lw_border, rgrid, with_text=False):\n    \"\"\"\n    Create a full figure with the Matplotlib logo.\n\n    Parameters\n    ----------\n    height_px : int\n        Height of the figure in pixel.\n    lw_bars : float\n        The linewidth of the bar border.\n    lw_grid : float\n        The linewidth of the grid.\n    lw_border : float\n        The linewidth of icon border.\n    rgrid : sequence of float\n        The radial grid positions.\n    with_text : bool\n        Whether to draw only the icon or to include 'matplotlib' as text.\n    \"\"\"\n    dpi = 100\n    height = height_px / dpi\n    figsize = (5 * height, height) if with_text else (height, height)\n    fig = plt.figure(figsize=figsize, dpi=dpi)\n    fig.patch.set_alpha(0)\n\n    if with_text:\n        create_text_axes(fig, height_px)\n    ax_pos = (0.535, 0.12, .17, 0.75) if with_text else (0.03, 0.03, .94, .94)\n    ax = create_icon_axes(fig, ax_pos, lw_bars, lw_grid, lw_border, rgrid)\n\n    return fig, ax"}]},{"title":"Displaying the Logos","body":["In this step, we will display the Matplotlib logos of different sizes."],"code":[{"lang":"python","text":"# A large logo:\nmake_logo(height_px=110, lw_bars=0.7, lw_grid=0.5, lw_border=1,\n          rgrid=[1, 3, 5, 7])\n\n# A small 32px logo:\nmake_logo(height_px=32, lw_bars=0.3, lw_grid=0.3, lw_border=0.3, rgrid=[5])\n\n# A large logo including text, as used on the Matplotlib website.\nmake_logo(height_px=110, lw_bars=0.7, lw_grid=0.5, lw_border=1,\n          rgrid=[1, 3, 5, 7], with_text=True)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# A large logo:\nmake_logo(height_px=110, lw_bars=0.7, lw_grid=0.5, lw_border=1,\n          rgrid=[1, 3, 5, 7])\n\n# A small 32px logo:\nmake_logo(height_px=32, lw_bars=0.3, lw_grid=0.3, lw_border=0.3, rgrid=[5])\n\n# A large logo including text, as used on the Matplotlib website.\nmake_logo(height_px=110, lw_bars=0.7, lw_grid=0.5, lw_border=1,\n          rgrid=[1, 3, 5, 7], with_text=True)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-a-looking-glass-with-matplotlib":{"intro":"This lab will guide you through creating a looking glass effect using mouse events in Matplotlib. This example will allow you to inspect data in a circular area that can be moved around by clicking and dragging.","steps":[{"title":"Importing the Required Libraries","body":["Importing the Required Libraries","We need to import the Matplotlib library, NumPy library and the Matplotlib patches module. We will use these libraries to create our looking glass effect."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.patches as patches"}]},{"title":"Generating the Random Data","body":["We will generate two sets of random data using NumPy. This data will be plotted to create a scatterplot."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nx, y = np.random.rand(2, 200)"}]},{"title":"Creating the Figure and Axes","body":["We will create the figure and axes object using the subplots() function. We will also add a yellow circle patch to the axes object using the patches.Circle() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\ncirc = patches.Circle((0.5, 0.5), 0.25, alpha=0.8, fc='yellow')\nax.add_patch(circ)"}]},{"title":"Plotting the Data","body":["We will plot the random data generated in Step 2 using the plot() function twice. The first plot will have an alpha value of 0.2 and the second plot will have an alpha value of 1.0 and a clip path set to the yellow circle patch."],"code":[{"lang":"python","text":"ax.plot(x, y, alpha=0.2)\nline, = ax.plot(x, y, alpha=1.0, clip_path=circ)\nax.set_title(\"Left click and drag to move looking glass\")"}]},{"title":"Creating the Event Handler","body":["We will create an event handler class that will handle the mouse events needed to move the yellow circle patch around the plot. This class will contain three methods: on_press(), on_release(), and on_move()."],"code":[{"lang":"python","text":"class EventHandler:\n    def __init__(self):\n        fig.canvas.mpl_connect('button_press_event', self.on_press)\n        fig.canvas.mpl_connect('button_release_event', self.on_release)\n        fig.canvas.mpl_connect('motion_notify_event', self.on_move)\n        self.x0, self.y0 = circ.center\n        self.pressevent = None\n\n    def on_press(self, event):\n        if event.inaxes != ax:\n            return\n\n        if not circ.contains(event)[0]:\n            return\n\n        self.pressevent = event\n\n    def on_release(self, event):\n        self.pressevent = None\n        self.x0, self.y0 = circ.center\n\n    def on_move(self, event):\n        if self.pressevent is None or event.inaxes != self.pressevent.inaxes:\n            return\n\n        dx = event.xdata - self.pressevent.xdata\n        dy = event.ydata - self.pressevent.ydata\n        circ.center = self.x0 + dx, self.y0 + dy\n        line.set_clip_path(circ)\n        fig.canvas.draw()\n\nhandler = EventHandler()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"class EventHandler:\n    def __init__(self):\n        fig.canvas.mpl_connect('button_press_event', self.on_press)\n        fig.canvas.mpl_connect('button_release_event', self.on_release)\n        fig.canvas.mpl_connect('motion_notify_event', self.on_move)\n        self.x0, self.y0 = circ.center\n        self.pressevent = None\n\n    def on_press(self, event):\n        if event.inaxes != ax:\n            return\n\n        if not circ.contains(event)[0]:\n            return\n\n        self.pressevent = event\n\n    def on_release(self, event):\n        self.pressevent = None\n        self.x0, self.y0 = circ.center\n\n    def on_move(self, event):\n        if self.pressevent is None or event.inaxes != self.pressevent.inaxes:\n            return\n\n        dx = event.xdata - self.pressevent.xdata\n        dy = event.ydata - self.pressevent.ydata\n        circ.center = self.x0 + dx, self.y0 + dy\n        line.set_clip_path(circ)\n        fig.canvas.draw()\n\nhandler = EventHandler()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-plotting-lorenz-attractor-in-3d-using-python":{"intro":"This lab is a step-by-step tutorial for plotting Edward Lorenz's 1963 'Deterministic Nonperiodic Flow' in a 3-dimensional space using mplot3d. We will use Python and Matplotlib, which is a plotting library for the Python programming language.","steps":[{"title":"Import Libraries","body":["We start by importing the necessary libraries: Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the Lorenz Function","body":["We define the Lorenz function, which takes in three parameters and returns an array of three values. We use the default values s=10, r=28, and b=2.667 for the Lorenz parameters."],"code":[{"lang":"python","text":"def lorenz(xyz, *, s=10, r=28, b=2.667):\n    \"\"\"\n    Parameters\n    ----------\n    xyz : array-like, shape (3,)\n       Point of interest in three-dimensional space.\n    s, r, b : float\n       Parameters defining the Lorenz attractor.\n\n    Returns\n    -------\n    xyz_dot : array, shape (3,)\n       Values of the Lorenz attractor's partial derivatives at *xyz*.\n    \"\"\"\n    x, y, z = xyz\n    x_dot = s*(y - x)\n    y_dot = r*x - y - x*z\n    z_dot = x*y - b*z\n    return np.array([x_dot, y_dot, z_dot])"}]},{"title":"Set Up the Initial Parameters","body":["We set up the initial parameters for the simulation, including the time step dt, the number of steps num_steps, and the initial values for x, y, and z."],"code":[{"lang":"python","text":"dt = 0.01\nnum_steps = 10000\n\nxyzs = np.empty((num_steps + 1, 3))  # Need one more for the initial values\nxyzs[0] = (0., 1., 1.05)  # Set initial values"}]},{"title":"Calculate the Lorenz Attractor","body":["Calculate the Lorenz Attractor","We calculate the Lorenz Attractor by stepping through time and estimating the next point using the previous point and the Lorenz function."],"code":[{"lang":"python","text":"for i in range(num_steps):\n    xyzs[i + 1] = xyzs[i] + lorenz(xyzs[i]) * dt"}]},{"title":"Plot the Lorenz Attractor","body":["We plot the Lorenz Attractor using Matplotlib's mplot3d module."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')\n\nax.plot(*xyzs.T, lw=0.5)\nax.set_xlabel(\"X Axis\")\nax.set_ylabel(\"Y Axis\")\nax.set_zlabel(\"Z Axis\")\nax.set_title(\"Lorenz Attractor\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = plt.figure().add_subplot(projection='3d')\n\nax.plot(*xyzs.T, lw=0.5)\nax.set_xlabel(\"X Axis\")\nax.set_ylabel(\"Y Axis\")\nax.set_zlabel(\"Z Axis\")\nax.set_title(\"Lorenz Attractor\")\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-major-and-minor-ticks-in-matplotlib":{"intro":"In a Matplotlib plot, ticks are used to mark the position of data points on the axis. Major ticks are the larger ticks that denote the values of the data points and minor ticks are the smaller ticks that are placed between the major ticks. This tutorial shows how to use major and minor ticks in Matplotlib.","steps":[{"title":"Import the necessary libraries and create data","body":["Import the necessary libraries and create data","First, we import the necessary libraries, i.e., Matplotlib and NumPy. Then we create data to plot. In this example, we create a numpy array \"t\" and calculate another numpy array \"s\" using t."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Create data\nt = np.arange(0.0, 100.0, 0.1)\ns = np.sin(0.1 * np.pi * t) * np.exp(-t * 0.01)"}]},{"title":"Plot the data","body":["Next, we create a figure and axis object and plot the data on the axis."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot(t, s)"}]},{"title":"Set the major and minor locators","body":["Set the major and minor locators","Here, we set the major locator to place ticks at multiples of 20, set the major formatter to label the major ticks with \".0f\" formatting, and set the minor locator to place ticks at multiples of 5."],"code":[{"lang":"python","text":"# Set the major locator\nax.xaxis.set_major_locator(MultipleLocator(20))\n# Set the major formatter\nax.xaxis.set_major_formatter('{x:.0f}')\n# Set the minor locator\nax.xaxis.set_minor_locator(MultipleLocator(5))"}]},{"title":"Display the plot","body":[],"code":[{"lang":"python","text":"plt.show()"}]},{"title":"Automatic tick selection for major and minor ticks","body":["Automatic tick selection for major and minor ticks","In this step, we create new data and plot it. Then we set the minor locator to automatically select the number of minor ticks. After that, we set the tick parameters, i.e., the width and length of the ticks and their color, for both major and minor ticks. Finally, we display the plot."],"code":[{"lang":"python","text":"# Create data\nt = np.arange(0.0, 100.0, 0.01)\ns = np.sin(2 * np.pi * t) * np.exp(-t * 0.01)\n\n# Plot the data\nfig, ax = plt.subplots()\nax.plot(t, s)\n\n# Set the minor locator\nax.xaxis.set_minor_locator(AutoMinorLocator())\n\n# Set the tick parameters\nax.tick_params(which='both', width=2)\nax.tick_params(which='major', length=7)\nax.tick_params(which='minor', length=4, color='r')\n\n# Display the plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create data\nt = np.arange(0.0, 100.0, 0.01)\ns = np.sin(2 * np.pi * t) * np.exp(-t * 0.01)\n\n# Plot the data\nfig, ax = plt.subplots()\nax.plot(t, s)\n\n# Set the minor locator\nax.xaxis.set_minor_locator(AutoMinorLocator())\n\n# Set the tick parameters\nax.tick_params(which='both', width=2)\nax.tick_params(which='major', length=7)\nax.tick_params(which='minor', length=4, color='r')\n\n# Display the plot\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-room-for-ylabel":{"intro":"Matplotlib is a data visualization library in Python that provides a variety of tools and techniques to create visually appealing graphs. Sometimes, it is necessary to make room for the y-label to avoid overlapping or truncating the text. This lab will show you how to use the axes_grid module to make room for the y-label in Matplotlib.","steps":[{"title":"Import Libraries and Create a Figure","body":["Import Libraries and Create a Figure","The first step is to import the necessary libraries and create a figure. We use the matplotlib.pyplot module to create a figure and the mpl_toolkits.axes_grid1 module to make room for the y-label."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axes_grid1 import make_axes_locatable\nfrom mpl_toolkits.axes_grid1.axes_divider import make_axes_area_auto_adjustable\n\nfig = plt.figure()\nax = fig.add_axes([0, 0, 1, 1])"}]},{"title":"Set Y-Ticks and Labels","body":["In this step, we set the y-ticks and labels for the y-axis. We use the set_yticks method to set the location of the y-tick and the labels parameter to set the label for the y-tick."],"code":[{"lang":"python","text":"ax.set_yticks([0.5], labels=[\"very long label\"])"}]},{"title":"Make Room for Y-Label","body":["Now, we use the make_axes_area_auto_adjustable method to make room for the y-label. This method automatically adjusts the size of the axes to accommodate the y-label."],"code":[{"lang":"python","text":"make_axes_area_auto_adjustable(ax)"}]},{"title":"Create a Figure with Two Axes","body":["In this step, we create a figure with two axes. We use the add_axes method to add two axes to the figure. We also set the y-tick label for the first axis and the title for the second axis."],"code":[{"lang":"python","text":"fig = plt.figure()\nax1 = fig.add_axes([0, 0, 1, 0.5])\nax2 = fig.add_axes([0, 0.5, 1, 0.5])\n\nax1.set_yticks([0.5], labels=[\"very long label\"])\nax1.set_ylabel(\"Y label\")\n\nax2.set_title(\"Title\")"}]},{"title":"Make Room for Y-Label and Adjust Axes","body":["Make Room for Y-Label and Adjust Axes","In this step, we use the make_axes_area_auto_adjustable method to make room for the y-label in both axes. We also use the use_axes parameter to specify the axes to be adjusted and the pad parameter to adjust the spacing between the axes."],"code":[{"lang":"python","text":"make_axes_area_auto_adjustable(ax1, pad=0.1, use_axes=[ax1, ax2])\nmake_axes_area_auto_adjustable(ax2, pad=0.1, use_axes=[ax1, ax2])"}]},{"title":"Create a Figure with Two Adjustable Axes","body":["Create a Figure with Two Adjustable Axes","In this step, we create a figure with two adjustable axes. We use the make_axes_locatable method to create a divider that allows the axes to be adjusted. We add a new axis to the right of the first axis using the append_axes method."],"code":[{"lang":"python","text":"fig = plt.figure()\nax1 = fig.add_axes([0, 0, 1, 1])\ndivider = make_axes_locatable(ax1)\nax2 = divider.append_axes(\"right\", \"100%\", pad=0.3, sharey=ax1)\nfig.add_axes(ax2)"}]},{"title":"Adjust the Axes and Make Room for Y-Label","body":["Adjust the Axes and Make Room for Y-Label","In this step, we use the add_auto_adjustable_area method to adjust the axes and make room for the y-label. We also set the title and x-label for the second axis."],"code":[{"lang":"python","text":"divider.add_auto_adjustable_area(use_axes=[ax1], pad=0.1,\n                                 adjust_dirs=[\"left\"])\ndivider.add_auto_adjustable_area(use_axes=[ax2], pad=0.1,\n                                 adjust_dirs=[\"right\"])\ndivider.add_auto_adjustable_area(use_axes=[ax1, ax2], pad=0.1,\n                                 adjust_dirs=[\"top\", \"bottom\"])\n\nax1.set_yticks([0.5], labels=[\"very long label\"])\nax2.set_title(\"Title\")\nax2.set_xlabel(\"X - Label\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"divider.add_auto_adjustable_area(use_axes=[ax1], pad=0.1,\n                                 adjust_dirs=[\"left\"])\ndivider.add_auto_adjustable_area(use_axes=[ax2], pad=0.1,\n                                 adjust_dirs=[\"right\"])\ndivider.add_auto_adjustable_area(use_axes=[ax1, ax2], pad=0.1,\n                                 adjust_dirs=[\"top\", \"bottom\"])\n\nax1.set_yticks([0.5], labels=[\"very long label\"])\nax2.set_title(\"Title\")\nax2.set_xlabel(\"X - Label\")"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-python-matplotlib-mandelbrot-visualization":{"intro":"This lab will guide you through generating a shaded and power-normalized rendering of the Mandelbrot set using Python's Matplotlib library.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the libraries we will be using: NumPy, Matplotlib, and Colors."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom matplotlib import colors"}]},{"title":"Define the Mandelbrot Set Function","body":["Define the Mandelbrot Set Function","Next, we will define a function that generates the Mandelbrot set. The function takes in several parameters:","• xmin, xmax, ymin, ymax: the minimum and maximum values for the x and y axes • xn and yn: the number of points to generate along each axis • maxiter: the maximum number of iterations to perform for each point • horizon: the maximum value at which to consider a point to be part of the set"],"code":[{"lang":"python","text":"def mandelbrot_set(xmin, xmax, ymin, ymax, xn, yn, maxiter, horizon=2.0):\n    X = np.linspace(xmin, xmax, xn).astype(np.float32)\n    Y = np.linspace(ymin, ymax, yn).astype(np.float32)\n    C = X + Y[:, None] * 1j\n    N = np.zeros_like(C, dtype=int)\n    Z = np.zeros_like(C)\n    for n in range(maxiter):\n        I = abs(Z) < horizon\n        N[I] = n\n        Z[I] = Z[I]**2 + C[I]\n    N[N == maxiter-1] = 0\n    return Z, N"}]},{"title":"Generate the Mandelbrot Set","body":["Now we will generate the Mandelbrot set by calling the mandelbrot_set function with our desired parameters. This will give us two arrays:","• Z: the final values of the complex numbers we iterated over • N: the number of iterations performed for each point before it was determined to be part of the set"],"code":[{"lang":"python","text":"xmin, xmax, xn = -2.25, +0.75, 3000 // 2\nymin, ymax, yn = -1.25, +1.25, 2500 // 2\nmaxiter = 200\nhorizon = 2.0 ** 40\nlog_horizon = np.log2(np.log(horizon))\nZ, N = mandelbrot_set(xmin, xmax, ymin, ymax, xn, yn, maxiter, horizon)"}]},{"title":"Normalize the Data","body":["In order to create a shaded and power-normalized rendering of the Mandelbrot set, we need to normalize our data. We will do this using the following formula:","M = N + 1 - np.log2(np.log(abs(Z))) + log_horizon"],"code":[{"lang":"python","text":"with np.errstate(invalid='ignore'):\n    M = np.nan_to_num(N + 1 - np.log2(np.log(abs(Z))) + log_horizon)"}]},{"title":"Create the Plot","body":["Now that we have our normalized data, we can create the plot. We will use the imshow function to display the data as an image, and we will also add some text to the plot to indicate what we are looking at."],"code":[{"lang":"python","text":"dpi = 72\nwidth = 10\nheight = 10*yn/xn\nfig = plt.figure(figsize=(width, height), dpi=dpi)\nax = fig.add_axes([0, 0, 1, 1], frameon=False, aspect=1)\n\nlight = colors.LightSource(azdeg=315, altdeg=10)\nM = light.shade(M, cmap=plt.cm.hot, vert_exag=1.5,\n                norm=colors.PowerNorm(0.3), blend_mode='hsv')\nax.imshow(M, extent=[xmin, xmax, ymin, ymax], interpolation=\"bicubic\")\nax.set_xticks([])\nax.set_yticks([])\n\nyear = time.strftime(\"%Y\")\ntext = (\"The Mandelbrot fractal set\\n\"\n        \"Rendered with matplotlib %s, %s - https://matplotlib.org\"\n        % (matplotlib.__version__, year))\nax.text(xmin+.025, ymin+.025, text, color=\"white\", fontsize=12, alpha=0.5)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"dpi = 72\nwidth = 10\nheight = 10*yn/xn\nfig = plt.figure(figsize=(width, height), dpi=dpi)\nax = fig.add_axes([0, 0, 1, 1], frameon=False, aspect=1)\n\nlight = colors.LightSource(azdeg=315, altdeg=10)\nM = light.shade(M, cmap=plt.cm.hot, vert_exag=1.5,\n                norm=colors.PowerNorm(0.3), blend_mode='hsv')\nax.imshow(M, extent=[xmin, xmax, ymin, ymax], interpolation=\"bicubic\")\nax.set_xticks([])\nax.set_yticks([])\n\nyear = time.strftime(\"%Y\")\ntext = (\"The Mandelbrot fractal set\\n\"\n        \"Rendered with matplotlib %s, %s - https://matplotlib.org\"\n        % (matplotlib.__version__, year))\nax.text(xmin+.025, ymin+.025, text, color=\"white\", fontsize=12, alpha=0.5)\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-customizing-matplotlib-visualizations-with-m":{"intro":"Matplotlib is a popular Python library used to create visualizations, including charts, graphs, and plots. One of the key components of Matplotlib is markers, which are used to represent data points on a plot. Markers come in various shapes, sizes, and styles, and can be customized to fit a specific data set. In this lab, you will learn how to use Matplotlib markers to create custom visualizations that effectively communicate your data.","steps":[{"title":"Unfilled Markers","body":["Unfilled markers are single-colored. The following code demonstrates how to create unfilled markers:"],"code":[{"lang":"python","text":"unfilled_markers = [m for m, func in Line2D.markers.items()\n                    if func != 'nothing' and m not in Line2D.filled_markers]\n\nfor ax, markers in zip(axs, split_list(unfilled_markers)):\n    for y, marker in enumerate(markers):\n        ax.text(-0.5, y, repr(marker), **text_style)\n        ax.plot([y] * 3, marker=marker, **marker_style)\n    format_axes(ax)"}]},{"title":"Filled Markers","body":["Filled markers are the opposite of unfilled markers. The following code demonstrates how to create filled markers:"],"code":[{"lang":"python","text":"fig, axs = plt.subplots(ncols=2)\nfig.suptitle('Filled markers', fontsize=14)\nfor ax, markers in zip(axs, split_list(Line2D.filled_markers)):\n    for y, marker in enumerate(markers):\n        ax.text(-0.5, y, repr(marker), **text_style)\n        ax.plot([y] * 3, marker=marker, **marker_style)\n    format_axes(ax)"}]},{"title":"Marker Fill Styles","body":["The edge color and fill color of filled markers can be specified separately. Additionally, the fillstyle can be configured to be unfilled, fully filled, or half-filled in various directions. The half-filled styles use markerfacecoloralt as a secondary fill color. The following code demonstrates how to create marker fill styles:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfig.suptitle('Marker fillstyle', fontsize=14)\nfig.subplots_adjust(left=0.4)\n\nfilled_marker_style = dict(marker='o', linestyle=':', markersize=15,\n                           color='darkgrey',\n                           markerfacecolor='tab:blue',\n                           markerfacecoloralt='lightsteelblue',\n                           markeredgecolor='brown')\n\nfor y, fill_style in enumerate(Line2D.fillStyles):\n    ax.text(-0.5, y, repr(fill_style), **text_style)\n    ax.plot([y] * 3, fillstyle=fill_style, **filled_marker_style)\nformat_axes(ax)"}]},{"title":"Markers Created from TeX Symbols","body":["Markers Created from TeX Symbols","Use :ref:MathText <mathtext>, to use custom marker symbols, like e.g. \"$\\u266B$\". For an overview over the STIX font symbols refer to the STIX font table <http://www.stixfonts.org/allGlyphs.html>\\_. Also see the :doc:/gallery/text_labels_and_annotations/stix_fonts_demo."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfig.suptitle('Mathtext markers', fontsize=14)\nfig.subplots_adjust(left=0.4)\n\nmarker_style.update(markeredgecolor=\"none\", markersize=15)\nmarkers = [\"$1$\", r\"$\\frac{1}{2}$\", \"$f$\", \"$\\u266B$\", r\"$\\mathcal{A}$\"]\n\nfor y, marker in enumerate(markers):\n    # Escape dollars so that the text is written \"as is\", not as mathtext.\n    ax.text(-0.5, y, repr(marker).replace(\"$\", r\"\\$\"), **text_style)\n    ax.plot([y] * 3, marker=marker, **marker_style)\nformat_axes(ax)"}]},{"title":"Markers Created from Paths","body":["Any ~.path.Path can be used as a marker. The following example shows two simple paths _star_ and _circle_, and a more elaborate path of a circle with a cut-out star."],"code":[{"lang":"python","text":"import numpy as np\n\nimport matplotlib.path as mpath\n\nstar = mpath.Path.unit_regular_star(6)\ncircle = mpath.Path.unit_circle()\n# concatenate the circle with an internal cutout of the star\ncut_star = mpath.Path(\n    vertices=np.concatenate([circle.vertices, star.vertices[::-1, ...]]),\n    codes=np.concatenate([circle.codes, star.codes]))\n\nfig, ax = plt.subplots()\nfig.suptitle('Path markers', fontsize=14)\nfig.subplots_adjust(left=0.4)\n\nmarkers = {'star': star, 'circle': circle, 'cut_star': cut_star}\n\nfor y, (name, marker) in enumerate(markers.items()):\n    ax.text(-0.5, y, name, **text_style)\n    ax.plot([y] * 3, marker=marker, **marker_style)\nformat_axes(ax)"}]},{"title":"Advanced Marker Modifications with Transform","body":["Advanced Marker Modifications with Transform","Markers can be modified by passing a transform to the MarkerStyle constructor. Following example shows how a supplied rotation is applied to several marker shapes."],"code":[{"lang":"python","text":"common_style = {k: v for k, v in filled_marker_style.items() if k != 'marker'}\nangles = [0, 10, 20, 30, 45, 60, 90]\n\nfig, ax = plt.subplots()\nfig.suptitle('Rotated markers', fontsize=14)\n\nax.text(-0.5, 0, 'Filled marker', **text_style)\nfor x, theta in enumerate(angles):\n    t = Affine2D().rotate_deg(theta)\n    ax.plot(x, 0, marker=MarkerStyle('o', 'left', t), **common_style)\n\nax.text(-0.5, 1, 'Un-filled marker', **text_style)\nfor x, theta in enumerate(angles):\n    t = Affine2D().rotate_deg(theta)\n    ax.plot(x, 1, marker=MarkerStyle('1', 'left', t), **common_style)\n\nax.text(-0.5, 2, 'Equation marker', **text_style)\nfor x, theta in enumerate(angles):\n    t = Affine2D().rotate_deg(theta)\n    eq = r'$\\frac{1}{x}$'\n    ax.plot(x, 2, marker=MarkerStyle(eq, 'left', t), **common_style)\n\nfor x, theta in enumerate(angles):\n    ax.text(x, 2.5, f\"{theta}°\", horizontalalignment=\"center\")\nformat_axes(ax)\n\nfig.tight_layout()"}]},{"title":"Setting Marker Cap Style and Join Style","body":["Setting Marker Cap Style and Join Style","Markers have default cap and join styles, but these can be customized when creating a MarkerStyle."],"code":[{"lang":"python","text":"from matplotlib.markers import CapStyle, JoinStyle\n\nmarker_inner = dict(markersize=35,\n                    markerfacecolor='tab:blue',\n                    markerfacecoloralt='lightsteelblue',\n                    markeredgecolor='brown',\n                    markeredgewidth=8,\n                    )\n\nmarker_outer = dict(markersize=35,\n                    markerfacecolor='tab:blue',\n                    markerfacecoloralt='lightsteelblue',\n                    markeredgecolor='white',\n                    markeredgewidth=1,\n                    )\n\nfig, ax = plt.subplots()\nfig.suptitle('Marker CapStyle', fontsize=14)\nfig.subplots_adjust(left=0.1)\n\nfor y, cap_style in enumerate(CapStyle):\n    ax.text(-0.5, y, cap_style.name, **text_style)\n    for x, theta in enumerate(angles):\n        t = Affine2D().rotate_deg(theta)\n        m = MarkerStyle('1', transform=t, capstyle=cap_style)\n        ax.plot(x, y, marker=m, **marker_inner)\n        ax.plot(x, y, marker=m, **marker_outer)\n        ax.text(x, len(CapStyle) - .5, f'{theta}°', ha='center')\nformat_axes(ax)"}]},{"title":"Modifying the Join Style","body":["The join style of markers can also be modified in a similar manner."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfig.suptitle('Marker JoinStyle', fontsize=14)\nfig.subplots_adjust(left=0.05)\n\nfor y, join_style in enumerate(JoinStyle):\n    ax.text(-0.5, y, join_style.name, **text_style)\n    for x, theta in enumerate(angles):\n        t = Affine2D().rotate_deg(theta)\n        m = MarkerStyle('*', transform=t, joinstyle=join_style)\n        ax.plot(x, y, marker=m, **marker_inner)\n        ax.text(x, len(JoinStyle) - .5, f'{theta}°', ha='center')\nformat_axes(ax)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nfig.suptitle('Marker JoinStyle', fontsize=14)\nfig.subplots_adjust(left=0.05)\n\nfor y, join_style in enumerate(JoinStyle):\n    ax.text(-0.5, y, join_style.name, **text_style)\n    for x, theta in enumerate(angles):\n        t = Affine2D().rotate_deg(theta)\n        m = MarkerStyle('*', transform=t, joinstyle=join_style)\n        ax.plot(x, y, marker=m, **marker_inner)\n        ax.text(x, len(JoinStyle) - .5, f'{theta}°', ha='center')\nformat_axes(ax)\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-marker-customization-tutorial":{"intro":"This tutorial will guide you through the process of using the markevery property of Line2D to draw markers at a subset of data points in Matplotlib. We will cover various ways to specify the markers, including using integers, tuples, lists, slices, and floats. We will also explore how markevery behaves with linear and logarithmic scales, as well as with zoomed and polar plots.","steps":[{"title":"Define the Data Points","body":["First, we define the data points that we will use for our plots. In this example, we use numpy to generate a set of x and y values for a sine wave."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# define a list of markevery cases to plot\ncases = [\n    None,\n    8,\n    (30, 8),\n    [16, 24, 32],\n    [0, -1],\n    slice(100, 200, 3),\n    0.1,\n    0.4,\n    (0.2, 0.4)\n]\n\n# data points\ndelta = 0.11\nx = np.linspace(0, 10 - 2 * delta, 200) + delta\ny = np.sin(x) + 1.0 + delta"}]},{"title":"Create Plots with Linear Scales","body":["Create Plots with Linear Scales","Next, we create a set of subplots to show how markevery behaves with linear scales. We iterate through the cases list and plot each case on a separate subplot. We use the markevery parameter to specify which data points to mark."],"code":[{"lang":"python","text":"# create plots with linear scales\nfig, axs = plt.subplots(3, 3, figsize=(10, 6), layout='constrained')\nfor ax, markevery in zip(axs.flat, cases):\n    ax.set_title(f'markevery={markevery}')\n    ax.plot(x, y, 'o', ls='-', ms=4, markevery=markevery)"}]},{"title":"Create Plots with Logarithmic Scales","body":["Create Plots with Logarithmic Scales","We repeat the previous step, but this time with logarithmic scales. We note that the logarithmic scale causes a visual asymmetry in the marker distance for integer-based subsampling, while fraction-based subsampling creates even distributions."],"code":[{"lang":"python","text":"# create plots with logarithmic scales\nfig, axs = plt.subplots(3, 3, figsize=(10, 6), layout='constrained')\nfor ax, markevery in zip(axs.flat, cases):\n    ax.set_title(f'markevery={markevery}')\n    ax.set_xscale('log')\n    ax.set_yscale('log')\n    ax.plot(x, y, 'o', ls='-', ms=4, markevery=markevery)"}]},{"title":"Create Zoomed Plots","body":["We create another set of subplots, this time to show how markevery behaves on zoomed plots. We note that integer-based subsampling selects points from the underlying data and is independent of the view, while float-based subsampling is related to the Axes diagonal and changes the displayed data range."],"code":[{"lang":"python","text":"# create zoomed plots\nfig, axs = plt.subplots(3, 3, figsize=(10, 6), layout='constrained')\nfor ax, markevery in zip(axs.flat, cases):\n    ax.set_title(f'markevery={markevery}')\n    ax.plot(x, y, 'o', ls='-', ms=4, markevery=markevery)\n    ax.set_xlim((6, 6.7))\n    ax.set_ylim((1.1, 1.7))"}]},{"title":"Create Polar Plots","body":["Finally, we create a set of subplots to show how markevery behaves on polar plots. We note that the behavior is similar to that on linear scales."],"code":[{"lang":"python","text":"# create polar plots\nr = np.linspace(0, 3.0, 200)\ntheta = 2 * np.pi * r\n\nfig, axs = plt.subplots(3, 3, figsize=(10, 6), layout='constrained',\n                        subplot_kw={'projection': 'polar'})\nfor ax, markevery in zip(axs.flat, cases):\n    ax.set_title(f'markevery={markevery}')\n    ax.plot(theta, r, 'o', ls='-', ms=4, markevery=markevery)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# create polar plots\nr = np.linspace(0, 3.0, 200)\ntheta = 2 * np.pi * r\n\nfig, axs = plt.subplots(3, 3, figsize=(10, 6), layout='constrained',\n                        subplot_kw={'projection': 'polar'})\nfor ax, markevery in zip(axs.flat, cases):\n    ax.set_title(f'markevery={markevery}')\n    ax.plot(theta, r, 'o', ls='-', ms=4, markevery=markevery)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-plotting-masked-and-nan-values":{"intro":"In data visualization, it is common to encounter missing data that needs to be plotted. In this tutorial, we will learn how to plot data with missing values using Matplotlib. We will explore three methods: removing undesired data points, masking points, and setting values to NaN.","steps":[{"title":"Import the Required Libraries","body":["We need to import the libraries we will be using in this tutorial. We will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data for Plotting","body":["We will create data to plot using NumPy. We will generate 31 data points between -pi/2 and pi/2 and calculate the cosine of these values raised to the power of 3."],"code":[{"lang":"python","text":"x = np.linspace(-np.pi/2, np.pi/2, 31)\ny = np.cos(x)**3"}]},{"title":"Remove Points","body":["We will remove points where y > 0.7. We will create a new x array and y array with only the remaining points."],"code":[{"lang":"python","text":"x2 = x[y <= 0.7]\ny2 = y[y <= 0.7]"}]},{"title":"Mask Points","body":["We will mask points where y > 0.7 using a masked array. We will create a new y array with masked values."],"code":[{"lang":"python","text":"y3 = np.ma.masked_where(y > 0.7, y)"}]},{"title":"Set to NaN","body":["We will set to NaN where y > 0.7. We will create a new y array with NaN values."],"code":[{"lang":"python","text":"y4 = y.copy()\ny4[y3 > 0.7] = np.nan"}]},{"title":"Plot the Data","body":["We will plot all four datasets using different markers and colors to differentiate them."],"code":[{"lang":"python","text":"plt.plot(x*0.1, y, 'o-', color='lightgrey', label='No mask')\nplt.plot(x2*0.4, y2, 'o-', label='Points removed')\nplt.plot(x*0.7, y3, 'o-', label='Masked values')\nplt.plot(x*1.0, y4, 'o-', label='NaN values')\nplt.legend()\nplt.title('Masked and NaN data')\nplt.show()"}]},{"title":"Interpret the Plot","body":["The resulting plot will have four lines of different colors and markers. The first line (light grey) represents the original data with no masking. The second line (orange) represents the data with undesired points removed. The third line (green) represents the data with masked values. The fourth line (blue) represents the data with NaN values. This plot shows how missing data can be visualized using different methods."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-convert-texts-to-images":{"intro":"In this lab, we will learn how to use Python's Matplotlib library to convert texts to images. This is useful when we want to include text in an image or visualization, or when we want to create images of text for use in machine learning or computer vision applications.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","We will start by importing the necessary libraries, which include Matplotlib and BytesIO."],"code":[{"lang":"python","text":"from io import BytesIO\nimport matplotlib.pyplot as plt\nfrom matplotlib.figure import Figure\nfrom matplotlib.transforms import IdentityTransform"}]},{"title":"Convert text to RGBA","body":["To convert text to an image, we will draw it on an empty and transparent figure, save the figure to a temporary buffer, and then load the buffer using plt.imread."],"code":[{"lang":"python","text":"def text_to_rgba(s, *, dpi, **kwargs):\n    fig = Figure(facecolor=\"none\")\n    fig.text(0, 0, s, **kwargs)\n    with BytesIO() as buf:\n        fig.savefig(buf, dpi=dpi, format=\"png\", bbox_inches=\"tight\", pad_inches=0)\n        buf.seek(0)\n        rgba = plt.imread(buf)\n    return rgba"}]},{"title":"Draw text images to a figure","body":["Once we have converted the text to an RGBA image, we can draw it to a figure using .Figure.figimage."],"code":[{"lang":"python","text":"fig = plt.figure()\nrgba1 = text_to_rgba(r\"IQ: $\\sigma_i=15$\", color=\"blue\", fontsize=20, dpi=200)\nrgba2 = text_to_rgba(r\"some other string\", color=\"red\", fontsize=20, dpi=200)\n\nfig.figimage(rgba1, 100, 50)\nfig.figimage(rgba2, 100, 150)\n\nplt.show()"}]},{"title":"Draw texts to a figure with positioning in pixel coordinates","body":["Draw texts to a figure with positioning in pixel coordinates","Alternatively, we can directly draw text to a figure with positioning in pixel coordinates by using .Figure.text together with .transforms.IdentityTransform."],"code":[{"lang":"python","text":"fig.text(100, 250, r\"IQ: $\\sigma_i=15$\", color=\"blue\", fontsize=20, transform=IdentityTransform())\nfig.text(100, 350, r\"some other string\", color=\"red\", fontsize=20, transform=IdentityTransform())\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.text(100, 250, r\"IQ: $\\sigma_i=15$\", color=\"blue\", fontsize=20, transform=IdentityTransform())\nfig.text(100, 350, r\"some other string\", color=\"red\", fontsize=20, transform=IdentityTransform())\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-using-matplotlib-s-latex-for-math-typesettin":{"intro":"In this tutorial, we will learn how to use Matplotlib's internal LaTeX parser and layout engine to create math text. We will be using Python programming language to write the code.","steps":[{"title":"Importing Libraries","body":["In this step, we will import the necessary libraries - matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Creating a Figure","body":["In this step, we will create a figure and an axis object using the subplots() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Adding a Plot","body":["In this step, we will add a plot to the axis object using the plot() function."],"code":[{"lang":"python","text":"ax.plot([1, 2, 3], label=r'$\\sqrt{x^2}$')\nax.legend()"}]},{"title":"Setting Labels","body":["In this step, we will set the labels for the x and y-axis using the set_xlabel() and set_ylabel() functions."],"code":[{"lang":"python","text":"ax.set_xlabel(r'$\\Delta_i^j$', fontsize=20)\nax.set_ylabel(r'$\\Delta_{i+1}^j$', fontsize=20)"}]},{"title":"Setting Title","body":["In this step, we will set the title for the plot using the set_title() function."],"code":[{"lang":"python","text":"ax.set_title(r'$\\Delta_i^j \\hspace{0.4} \\mathrm{versus} \\hspace{0.4} '\n             r'\\Delta_{i+1}^j$', fontsize=20)"}]},{"title":"Adding Text","body":["In this step, we will add text to the plot using the text() function."],"code":[{"lang":"python","text":"tex = r'$\\mathcal{R}\\prod_{i=\\alpha_{i+1}}^\\infty a_i\\sin(2 \\pi f x_i)$'\nax.text(1, 1.6, tex, fontsize=20, va='bottom')"}]},{"title":"Adjusting Layout","body":["In this step, we will adjust the layout of the plot using the tight_layout() function."],"code":[{"lang":"python","text":"fig.tight_layout()"}]},{"title":"Displaying the Plot","body":["In this step, we will display the plot using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"}};
